"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["6947"],{1043(e,n,r){r.r(n),r.d(n,{metadata:()=>t,default:()=>k,frontMatter:()=>l,contentTitle:()=>d,toc:()=>o});var t=JSON.parse('{"docId":"references/paper","permalink":"/no-NO/docs/references/paper","source":"@site/i18n/no-NO/lagune-docs-content/references/paper.mdx","title":"Security-Driven Hardening: en konvensjon for tiden med KI-assistert utvikling","sidebarLabel":"Metodeartikkel","description":"Metodikken Security-Driven Hardening (SDH): en kontekstbevisst Blue Team-konvensjon for revisjon og herding av programvare som er KI-assistert eller vibe-kodet.","keywords":["Security-Driven Hardening","SDH","defensiv sikkerhet","herding","hardening","spec-driven development","Lagune metodeartikkel"],"datePublished":"2026-11-09T06:15:06.000Z","dateModified":"2026-11-09T06:15:06.000Z","state":"translated","alternates":[{"locale":"en","permalink":"/docs/references/paper"},{"locale":"pt-BR","permalink":"/pt-BR/docs/references/paper"},{"locale":"es-ES","permalink":"/es-ES/docs/references/paper"},{"locale":"de-DE","permalink":"/de-DE/docs/references/paper"},{"locale":"fr-FR","permalink":"/fr-FR/docs/references/paper"},{"locale":"it-IT","permalink":"/it-IT/docs/references/paper"},{"locale":"tr-TR","permalink":"/tr-TR/docs/references/paper"},{"locale":"uk-UA","permalink":"/uk-UA/docs/references/paper"},{"locale":"ru-RU","permalink":"/ru-RU/docs/references/paper"},{"locale":"zh-CN","permalink":"/zh-CN/docs/references/paper"},{"locale":"ja-JP","permalink":"/ja-JP/docs/references/paper"},{"locale":"ko-KR","permalink":"/ko-KR/docs/references/paper"},{"locale":"hi-IN","permalink":"/hi-IN/docs/references/paper"},{"locale":"id-ID","permalink":"/id-ID/docs/references/paper"},{"locale":"th-TH","permalink":"/th-TH/docs/references/paper"},{"locale":"da-DK","permalink":"/da-DK/docs/references/paper"},{"locale":"no-NO","permalink":"/no-NO/docs/references/paper"},{"locale":"pl-PL","permalink":"/pl-PL/docs/references/paper"},{"locale":"ar-AE","permalink":"/ar-AE/docs/references/paper"}]}'),s=r(4848),i=r(8453);let l={id:"paper",title:"Security-Driven Hardening: en konvensjon for tiden med KI-assistert utvikling",sidebar_label:"Metodeartikkel",description:"Metodikken Security-Driven Hardening (SDH): en kontekstbevisst Blue Team-konvensjon for revisjon og herding av programvare som er KI-assistert eller vibe-kodet.",keywords:["Security-Driven Hardening","SDH","defensiv sikkerhet","herding","hardening","spec-driven development","Lagune metodeartikkel"],source_hash:"030038fc3c922aec5f2f0a11d4dc5a15b92756c7dd17606378f27ad1c018c82b"},d="Security-Driven Hardening (SDH): en konvensjon for tiden med KI-assistert utvikling",o=[{value:"Sammendrag",id:"sammendrag",level:2},{value:"I. Innledning: sikkerhetsgapet KI-assistert utvikling \xe5pnet",id:"i-innledning-sikkerhetsgapet-ki-assistert-utvikling-\xe5pnet",level:2},{value:"II. Bakgrunn og relatert arbeid",id:"ii-bakgrunn-og-relatert-arbeid",level:2},{value:"III. SDH: definisjon og designprinsipper",id:"iii-sdh-definisjon-og-designprinsipper",level:2},{value:"IV. Blue Team-flyten i 5 faser",id:"iv-blue-team-flyten-i-5-faser",level:2},{value:"charter (retningslinjer)",id:"charter-retningslinjer",level:3},{value:"detect (oppdagelse)",id:"detect-oppdagelse",level:3},{value:"plan (triage)",id:"plan-triage",level:3},{value:"harden (utbedring)",id:"harden-utbedring",level:3},{value:"verify (verifisering)",id:"verify-verifisering",level:3},{value:"V. Lukkbarhet: et funn har en sluttilstand",id:"v-lukkbarhet-et-funn-har-en-sluttilstand",level:2},{value:"VI. Dualiteten som utvider utviklerens kunnskap",id:"vi-dualiteten-som-utvider-utviklerens-kunnskap",level:2},{value:"VII. Ikke-kallbare spesialiseringer og prompt-on-demand",id:"vii-ikke-kallbare-spesialiseringer-og-prompt-on-demand",level:2},{value:"VIII. Tilstandsuavhengighet og ikke-autoritativ tilpasningsevne",id:"viii-tilstandsuavhengighet-og-ikke-autoritativ-tilpasningsevne",level:2},{value:"Tilstandsuavhengighet",id:"tilstandsuavhengighet",level:3},{value:"Ikke-autoritativ tilpasningsevne",id:"ikke-autoritativ-tilpasningsevne",level:3},{value:"IX. Den universelle forebyggende modusen: det samme forsvaret mens arbeidet bygges",id:"ix-den-universelle-forebyggende-modusen-det-samme-forsvaret-mens-arbeidet-bygges",level:2},{value:"X. Security-Driven Hardening versus Spec-Driven Development",id:"x-security-driven-hardening-versus-spec-driven-development",level:2},{value:"XI. Ingeni\xf8rmessig grundighet: sporingsdisiplinen",id:"xi-ingeni\xf8rmessig-grundighet-sporingsdisiplinen",level:2},{value:"XII. B\xe6reren: agentuavhengig arkitektur som bevis p\xe5 portabilitet",id:"xii-b\xe6reren-agentuavhengig-arkitektur-som-bevis-p\xe5-portabilitet",level:2},{value:"XIII. Gjennomg\xe5tt eksempel: SDH fra start til slutt",id:"xiii-gjennomg\xe5tt-eksempel-sdh-fra-start-til-slutt",level:2},{value:"XIV. N\xe5r du b\xf8r bruke SDH, og grensene",id:"xiv-n\xe5r-du-b\xf8r-bruke-sdh-og-grensene",level:2},{value:"XV. Diskusjon: posisjonering, grenser og hva SDH ikke hevder",id:"xv-diskusjon-posisjonering-grenser-og-hva-sdh-ikke-hevder",level:2},{value:"Den utvider, den erstatter ikke",id:"den-utvider-den-erstatter-ikke",level:3},{value:"Kun defensiv, per konstruksjon",id:"kun-defensiv-per-konstruksjon",level:3},{value:"Verifiseringen er reell, ikke teater",id:"verifiseringen-er-reell-ikke-teater",level:3},{value:"Determinismen er avgrenset og navngitt",id:"determinismen-er-avgrenset-og-navngitt",level:3},{value:"Kostnad og skala",id:"kostnad-og-skala",level:3},{value:"Brukeren har siste ord",id:"brukeren-har-siste-ord",level:3},{value:"Innvendinger og svar",id:"innvendinger-og-svar",level:3},{value:"XVI. Fallgruver, og hvordan SDH unng\xe5r dem strukturelt",id:"xvi-fallgruver-og-hvordan-sdh-unng\xe5r-dem-strukturelt",level:2},{value:"XVII. Videre arbeid",id:"xvii-videre-arbeid",level:2},{value:"XVIII. Konklusjon",id:"xviii-konklusjon",level:2},{value:"Referanser",id:"referanser",level:2},{value:"Vedlegg A: prinsippene, ordrett",id:"vedlegg-a-prinsippene-ordrett",level:2}];function a(e){let n={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:(0,s.jsx)(n.strong,{children:"Weslley Ara\xfajo"})}),"\n",(0,s.jsx)(n.li,{children:(0,s.jsx)(n.strong,{children:"Metodeartikkel, 2026."})}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"sammendrag",children:"Sammendrag"}),"\n",(0,s.jsx)(n.p,{children:"Security-Driven Hardening (SDH) er en strukturert, KI-drevet og kun defensiv sikkerhetsmetodikk for en tid der programvare i \xf8kende grad skrives av KI-agenter og av mennesker som ikke er sikkerhetsspesialister. I stedet for \xe5 kj\xf8re en generisk sjekkliste oppdager SDH f\xf8rst hva et system faktisk gj\xf8r (innlogging, filopplasting, betalinger, dataeksponering og s\xe5 videre), og driver deretter sikkerhetsarbeidet som er spesifikt for den konteksten. Metodikken styres av prinsipper som er sikre som standard, er rammet inn helt rundt forsvar og uttrykt i et enkelt spr\xe5k, slik at enhver bruker kan handle ut fra den."}),"\n",(0,s.jsxs)(n.p,{children:["Dette dokumentet argumenterer for at SDH er en manglende konvensjon, ikke ett enkelt verkt\xf8y. Sikkerhetskunnskapen ligger i metodikken og spesialiseringene som lastes ved behov, et grunnlag enhver bruker kan bygge videre p\xe5, og det lar den tjene en nybegynner og en ekspert gjennom den samme flyten. To egenskaper skiller den fra tidligere spec-first-tiln\xe6rminger ",(0,s.jsx)(n.code,{children:"[1]"}),". SDH er ",(0,s.jsx)(n.strong,{children:"tilstandsuavhengig"}),": Den tilpasser seg en tom mappe, et prosjekt under arbeid, \xe9n enkelt pull request eller en stor eldre kodebase, i hvilken som helst stack. Og SDH er ",(0,s.jsx)(n.strong,{children:"lukkbar"}),": En risiko som er verifisert lukket, tas ut av hele flyten, slik at funnet kommer til ro og \xe5pnes igjen f\xf8rst n\xe5r koden endres. SDH erstatter ikke sikkerhetsfolk eller spesialiserte Blue Team-verkt\xf8y. Den utvider utviklerens egen kunnskap, og jo mer en utvikler forst\xe5r av sikkerhet, desto mer kan vedkommende styre den."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Lagune"})," er referanseimplementasjonen, og den beviser at metodikken kan bygges og overf\xf8res. SDH tilbys som en konvensjon andre kan ta i bruk."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Stikkord"})}),"\n",(0,s.jsx)(n.p,{children:"KI-assistert utvikling, programvaresikkerhet, defensiv sikkerhet, spec-driven development, sikkerhetsherding, agentdrevne arbeidsflyter, lukkbarhet, kontekstbevisst sikkerhet, kunnskap ved behov, agentuavhengige verkt\xf8y."}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"i-innledning-sikkerhetsgapet-ki-assistert-utvikling-\xe5pnet",children:"I. Innledning: sikkerhetsgapet KI-assistert utvikling \xe5pnet"}),"\n",(0,s.jsxs)(n.p,{children:["Programvare blir i \xf8kende grad levert av mennesker, og av KI-agenter, som ikke p\xe5litelig kan gjenkjenne et usikkert m\xf8nster: en lekket hemmelighet, en manglende autorisasjonssjekk, en sp\xf8rring som kan injiseres. Dette er ikke eksotiske risikoer. De h\xf8rer til risikoklassene som dominerer virkelige hendelser, dokumentert i \xe5revis i offentlige referanser ",(0,s.jsx)(n.code,{children:"[6]"}),", ",(0,s.jsx)(n.code,{children:"[7]"}),", og nyere studier viser at en betydelig andel av KI-generert kode leveres med nettopp slike feil ",(0,s.jsx)(n.code,{children:"[8]"}),'. KI-kodeassistenter gjorde dette akutt ved \xe5 la ikke-utviklere levere ekte programvare, men gapet er bredere enn \xe9n enkelt m\xe5lgruppe. De fleste prosjekter f\xe5r aldri en sikkerhetsgjennomgang som er spesifikk for det de faktisk gj\xf8r. \xd8kosystemet blir skj\xf8rere for hver forhastet beslutning av typen "det funker, send det ut".']}),"\n",(0,s.jsx)(n.p,{children:"Generiske sikkerhetsr\xe5d lukker ikke dette gapet. En statisk sjekkliste er ikke spesifikk for det et system gj\xf8r, s\xe5 den oversv\xf8mmer et lite prosjekt med irrelevante punkter og g\xe5r likevel glipp av risikoen som betyr noe for akkurat det prosjektet. Problemet er ikke mangel p\xe5 sikkerhetskunnskap i verden. Problemet er \xe5 matche riktig kunnskap med systemet brukeren faktisk har foran seg, og \xe5 gj\xf8re det for noen som kanskje ikke vet hva det skal sp\xf8rres om."}),"\n",(0,s.jsxs)(n.p,{children:["SDH svarer p\xe5 dette med \xe9n enkelt inversjon: ",(0,s.jsx)(n.strong,{children:"sikkerhetskunnskapen ligger i spesifikasjonen og spesialiseringene som lastes ved behov, et grunnlag enhver bruker kan bygge videre p\xe5"}),". Metodikken oppdager konteksten, prioriterer risikoene den konteksten f\xf8rer med seg og veileder utbedringene, s\xe5 en utvikler og en ikke-utvikler bruker den samme flyten. Funnene og anbefalingene holdes i et enkelt spr\xe5k, s\xe5 de kan f\xf8lges opp uansett hvor teknisk leseren er. Eksperten blir ikke begrenset av dette, men forsterket, en dualitet vi utdyper i ",(0,s.jsx)(n.code,{children:"\xa7VI"}),"."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Kjerneinnsikt"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Kjerneinversjonen:"})," Sikkerhetskunnskapen ligger i spesifikasjonen og spesialiseringene som lastes ved behov, et grunnlag enhver bruker kan bygge videre p\xe5. Metodikken l\xe6rer hva systemet gj\xf8r og tilpasser sikkerhetsarbeidet til det, og den utvider det brukeren allerede kan."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'Tenk deg en utvikler som sier til en KI-assistent: "Appen min lar brukere laste opp et profilbilde." Uten en sikkerhetsgjennomgang lager assistenten fungerende kode som i det stille stoler p\xe5 alt klienten sender: den oppgitte filtypen, filnavnet, st\xf8rrelsen. Opplastingen g\xe5r i produksjon, og en fil forkledd som et bilde kan inneholde kode, et manipulert navn kan bryte ut av lagringsstien, en overdimensjonert fil kan t\xf8mme serveren for ressurser. Ingenting av dette synes i en demo, s\xe5 det g\xe5r i produksjon.'}),"\n",(0,s.jsx)(n.p,{children:'Den samme koden oppf\xf8rer seg annerledes n\xe5r den kj\xf8res gjennom SDH. Metodikken oppdager at systemet tar imot filer utenfra (oppdagelse), omsetter det til risikoene en opplasting f\xf8rer med seg (triage), foresl\xe5r \xe5 sjekke den faktiske filtypen og st\xf8rrelsen, gi filen nytt navn ved lagring og lagre den der kode ikke kan kj\xf8res (utbedring), og leser deretter resultatet og bekrefter at hvert sikringstiltak faktisk holder (verifisering). Utvikleren trengte aldri \xe5 kjenne uttrykket "ubegrenset filopplasting". Metodikken leverte det p\xe5 utviklerens vegne.'}),"\n",(0,s.jsx)(n.p,{children:"Dette dokumentet gir f\xf8lgende bidrag:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["En presis definisjon av SDH som metodikk, uavhengig av en bestemt implementasjon, med designprinsippene (",(0,s.jsx)(n.code,{children:"\xa7III"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["En defensiv livssyklus i fem faser der selve ansvarsdelingen er bidraget: Oppdagelsen finner aldri p\xe5, planleggingen leser aldri kode, bare \xe9n fase endrer kode, og verifiseringen myker aldri opp vurderingen sin (",(0,s.jsx)(n.code,{children:"\xa7IV"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Lukkbarhet"})," som metodisk standpunkt: Et enkelt funn har en sluttilstand, ikke en endel\xf8s l\xf8kke (",(0,s.jsx)(n.code,{children:"\xa7V"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["Dualiteten der metodikken ",(0,s.jsx)(n.strong,{children:"utvider utviklerens kunnskap"}),": \xe9n flyt som beskytter nybegynneren og forsterker eksperten (",(0,s.jsx)(n.code,{children:"\xa7VI"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Ikke-kallbare spesialiseringer og prompt-on-demand"}),": fokusert sikkerhetskunnskap agenten laster n\xe5r konteksten i prosjektet krever det, aldri som standard (",(0,s.jsx)(n.code,{children:"\xa7VII"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Tilstandsuavhengighet"})," og ",(0,s.jsx)(n.strong,{children:"ikke-autoritativ tilpasningsevne"}),": SDH passer til enhver utviklingstilstand og tilpasser seg scenarioet i stedet for \xe5 p\xe5tvinge et fast omfang (",(0,s.jsx)(n.code,{children:"\xa7VIII"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["En ",(0,s.jsx)(n.strong,{children:"forebyggende modus"}),": Det samme forsvaret kj\xf8res mens vanlig arbeid bygges, s\xe5 koden blir sikker som standard fra start og fasene har mindre \xe5 rette opp (",(0,s.jsx)(n.code,{children:"\xa7IX"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["En egen sammenligning med Spec-Driven Development, slekten SDH vokste ut av og deretter skilte lag med (",(0,s.jsx)(n.code,{children:"\xa7X"}),")."]}),"\n",(0,s.jsxs)(n.li,{children:["Ingeni\xf8rdisiplinene som lar metodikken overleve refaktoreringer og forbli uavhengig av enhver agent: sporing med identitet etter navn (",(0,s.jsx)(n.code,{children:"\xa7XI"}),") og en agentuavhengig b\xe6rer (",(0,s.jsx)(n.code,{children:"\xa7XII"}),")."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ii-bakgrunn-og-relatert-arbeid",children:"II. Bakgrunn og relatert arbeid"}),"\n",(0,s.jsxs)(n.p,{children:["SDH bygger p\xe5 tidligere arbeid. Den arver en velpr\xf8vd struktur fra spec-first, agentdrevet utvikling ",(0,s.jsx)(n.code,{children:"[1]"}),", ",(0,s.jsx)(n.code,{children:"[2]"}),", ",(0,s.jsx)(n.code,{children:"[3]"}),": maler, skr\xe5strekkommandoer en agent bruker, et styrende dokument og en agent som kj\xf8rer fasene. Den implementerer den strukturen p\xe5 nytt med et defensivt form\xe5l. Slektskapet er bevisst, og et av arbeidsprinsippene i SDH sier det rett ut: Bygg arbeidsflyten p\xe5 en velpr\xf8vd struktur, og ramm den deretter inn for sikkerhet."]}),"\n",(0,s.jsx)(n.p,{children:"SDH er ikke en statisk sjekkliste med generiske anbefalinger. En sjekkliste vet mye om sikkerhet generelt og ingenting om prosjektet foran den. SDH snur denne vektleggingen. Den bruker den f\xf8rste innsatsen p\xe5 oppdagelse, p\xe5 \xe5 l\xe6re hva systemet gj\xf8r, og f\xf8rst deretter henter den kunnskapen som oppdagelsen gj\xf8r relevant."}),"\n",(0,s.jsxs)(n.p,{children:["SDH erstatter heller ikke sikkerhetsfolk eller spesialiserte Blue Team-verkt\xf8y. Den utvider utviklerens kunnskap (",(0,s.jsx)(n.code,{children:"\xa7VI"}),"). Et team med en egen sikkerhetsfunksjon b\xf8r beholde den. SDH gir det teamet en strukturert b\xe6rer, og den gir et team uten en slik funksjon et forsvarbart grunnlag."]}),"\n",(0,s.jsxs)(n.p,{children:["SDH st\xe5r ogs\xe5 ved siden av deterministiske sikkerhetsskannere (statisk analyse, lintere) ",(0,s.jsx)(n.code,{children:"[4]"}),", ",(0,s.jsx)(n.code,{children:"[5]"}),". Disse verkt\xf8yene er verdifulle nettopp fordi de er deterministiske og repeterbare. SDH bygger for det meste p\xe5 agentens resonnering, som bytter streng determinisme mot kontekstbevissthet. Metodikken later ikke som noe annet. Der determinisme betyr noe, bygger den inn en deterministisk motor i resonneringen (",(0,s.jsx)(n.code,{children:"\xa7VII"}),"): Agenten avgj\xf8r om en inngangsverdi er verdt \xe5 sjekke, og et deterministisk program avgj\xf8r om verdien er farlig."]}),"\n",(0,s.jsxs)(n.p,{children:["Den mest direkte forgjengeren er Spec-Driven Development (SDD), familien av spec-first-metodikker som driver et bygg fremover fra en kj\xf8rbar spesifikasjon. Vi behandler SDD som en klasse. Den tydeligste formuleringen av den som praktikermetodikk er rapporten til Piskala ",(0,s.jsx)(n.code,{children:"[1]"}),", og det mest synlige agentdrevne verkt\xf8ysettet er Spec Kit fra GitHub ",(0,s.jsx)(n.code,{children:"[2]"}),", med OpenSpec ",(0,s.jsx)(n.code,{children:"[3]"})," som et annet verkt\xf8y fra samme familie. Disse er de kanoniske referansene for sammenligningen i ",(0,s.jsx)(n.code,{children:"\xa7X"}),"."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"iii-sdh-definisjon-og-designprinsipper",children:"III. SDH: definisjon og designprinsipper"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Security-Driven Hardening"})," er en strukturert, KI-drevet sikkerhetsmetodikk som gj\xf8r en kodebase sikrere ved \xe5 drive arbeidet fra en spesifikasjon agenten kj\xf8rer, i stedet for fra ad hoc-utbedringer. Navnet er inspirert av ",(0,s.jsx)(n.strong,{children:"Blue Teams"}),", forsvarerne innen sikkerhet. SDH handler om forsvar, herding og verifisering, aldri angrep."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Security-Driven Hardening (SDH):"})," En strukturert, KI-drevet og kun defensiv sikkerhetsmetodikk som f\xf8rst oppdager hva et system faktisk gj\xf8r og deretter driver det kontekstspesifikke sikkerhetsarbeidet, styrt av prinsipper som er sikre som standard og uttrykt i et enkelt spr\xe5k."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"SDH defineres av et sett bindende prinsipper. Hvert av dem er en regel, og hvert gir brukeren en bestemt garanti."}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Prinsipp"}),(0,s.jsx)(n.th,{children:"Regelen"}),(0,s.jsx)(n.th,{children:"Hva det garanterer brukeren"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Sikker som standard, i et enkelt spr\xe5k, likt for alle"}),(0,s.jsx)(n.td,{children:"Hver standardinnstilling, melding og utbedring er sikker fra start og forst\xe5elig for enhver leser, utvikler eller ikke. Ingen brukergruppe er privilegert."}),(0,s.jsx)(n.td,{children:"En nybegynner f\xe5r et sikkert grunnlag uten \xe5 be om det, og leser resultatet p\xe5 sine egne premisser."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Kontekstbevisst fremfor generisk"}),(0,s.jsx)(n.td,{children:"Hver fase starter fra konteksten som ble oppdaget i detect, og handler ut fra det systemet faktisk gj\xf8r."}),(0,s.jsx)(n.td,{children:"Anbefalingene passer prosjektet, ikke en sjekkliste. Sikkerhetskunnskapen ligger i spesifikasjonen og spesialiseringene som lastes ved behov, og utvider det brukeren tar med seg."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Fleksibel fremfor rigid"}),(0,s.jsx)(n.td,{children:"Prinsipper, krav og anbefalinger er utgangspunkter. Brukeren kan omformulere, droppe, legge til eller snevre inn hva som helst."}),(0,s.jsx)(n.td,{children:"Metodikken tilpasser seg prosjektet og brukeren, og blir aldri strengere enn brukeren \xf8nsker. Fleksibilitet svekker aldri grunnlaget som er sikkert som standard."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Avstem, aldri bare legg til"}),(0,s.jsx)(n.td,{children:"Artefakter er levende dokumenter, ikke logger. Hver kj\xf8ring sjekker hver oppf\xf8ring p\xe5 nytt: behold det som holder, skriv om det som er endret, fjern det som ikke lenger gjelder."}),(0,s.jsx)(n.td,{children:"Det som er registrert, gjenspeiler alltid n\xe5tiden, s\xe5 det forfaller aldri til et utdatert etterslep."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Kun defensiv"}),(0,s.jsx)(n.td,{children:"SDH reviderer, herder og verifiserer. Den lager aldri offensive verkt\xf8y, exploits for ondsinnet bruk eller teknikker for \xe5 unng\xe5 deteksjon for \xe5 gj\xf8re skade."}),(0,s.jsx)(n.td,{children:"Metodikken kan ikke gj\xf8res om til et v\xe5pen. Innhold med dobbel bruk forekommer bare i en tydelig defensiv ramme."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Spec-first, agentdrevet, innrettet mot sikkerhet"}),(0,s.jsx)(n.td,{children:"Arbeidsflyten bygges av maler, kommandoer, styrende sikkerhetsprinsipper og en agent som kj\xf8rer fasene."}),(0,s.jsx)(n.td,{children:"En velpr\xf8vd utviklingsstruktur, tatt i bruk p\xe5 nytt slik at agenten gj\xf8r det vesentlige sikkerhetsarbeidet."})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tabell 1."})," Designprinsippene i SDH og garantien hvert av dem gir brukeren."]}),"\n",(0,s.jsxs)(n.p,{children:["Disse prinsippene er ikke pynt. De er begrensningene hver fase nedenfor m\xe5 respektere, og diskusjonen i ",(0,s.jsx)(n.code,{children:"\xa7XV"})," vender tilbake til dem for \xe5 markere grensene for metodikken."]}),"\n",(0,s.jsx)(n.p,{children:"Resten av dokumentet utvikler ni navngitte pilarer. Det er delene en leser b\xf8r kunne holde i hodet, og delene et annet team ville implementert p\xe5 nytt for \xe5 kunne si at de praktiserer SDH."}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Pilar"}),(0,s.jsx)(n.th,{children:"Hva den gir"}),(0,s.jsx)(n.th,{children:"Seksjon"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Den kontekstbevisste inversjonen"}),(0,s.jsx)(n.td,{children:"Sikkerhetskunnskapen ligger i spesifikasjonen og spesialiseringene som lastes ved behov, s\xe5 en nybegynner og en ekspert deler \xe9n flyt."}),(0,s.jsxs)(n.td,{children:[(0,s.jsx)(n.code,{children:"\xa7I"}),", ",(0,s.jsx)(n.code,{children:"\xa7VI"})]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Den defensive livssyklusen i fem faser"}),(0,s.jsx)(n.td,{children:"Ansvarsdeling: retningslinjer, oppdagelse, triage, utbedring, verifisering, hver med \xe9n oppgave."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7IV"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Lukkbarhet"}),(0,s.jsx)(n.td,{children:"Et funn har en sluttilstand, ikke en endel\xf8s l\xf8kke. Lukket arbeid tas ut."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7V"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Dualiteten som utvider utviklerens kunnskap"}),(0,s.jsx)(n.td,{children:"\xc9n flyt som beskytter nybegynneren og forsterker eksperten, uten \xe5 erstatte noen av dem."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7VI"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Prompt-on-demand, ikke-kallbar kunnskap"}),(0,s.jsx)(n.td,{children:"Relevant sikkerhetskunnskap lastes for det prosjektet er, aldri som standard."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7VII"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Tilstandsuavhengighet og ikke-autoritativ tilpasningsevne"}),(0,s.jsx)(n.td,{children:"Passer til enhver utviklingstilstand i enhver stack, og tilpasser seg scenarioet i stedet for \xe5 p\xe5tvinge et omfang."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7VIII"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Den forebyggende modusen"}),(0,s.jsx)(n.td,{children:"Det samme forsvaret kj\xf8rer mens nytt arbeid bygges, s\xe5 koden blir sikker som standard fra start."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7IX"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Sporing med identitet etter navn"}),(0,s.jsx)(n.td,{children:"Et funn forblir ett element p\xe5 tvers av fasene, og en omd\xf8ping bryter koblingen p\xe5 bare ett sted."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7XI"})})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Den agentuavhengige b\xe6reren"}),(0,s.jsx)(n.td,{children:"Sikkerhetsverdien skrives \xe9n gang og er ikke avhengig av noen agent eller stack."}),(0,s.jsx)(n.td,{children:(0,s.jsx)(n.code,{children:"\xa7XII"})})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tabell 2."})," De ni navngitte pilarene i SDH og hvor hver av dem utvikles."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"iv-blue-team-flyten-i-5-faser",children:"IV. Blue Team-flyten i 5 faser"}),"\n",(0,s.jsx)(n.p,{children:"SDH strukturerer arbeidet som en defensiv livssyklus i fem faser (figur 1). Hver fase er rammet inn rundt forsvar, hver bygger p\xe5 den forrige, og fasene f\xf8lger reell Blue Team-aktivitet: fastsette retningslinjer, oppdage, triagere, utbedre, verifisere."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    charter["1 \xb7 charter (retningslinjer)<br/>leser: prosjektet, og brukerens beskrivelse hvis den finnes<br/>skriver: sikkerhetsprinsippene<br/>prinsippene beskriver risikoen de forebygger, i et enkelt spr\xe5k"]\n    detect["2 \xb7 detect (oppdagelse)<br/>leser: koden til brukeren<br/>skriver: kartleggingen<br/>oppdage, ikke finne p\xe5: registrer bare det koden underbygger"]\n    plan["3 \xb7 plan (triage)<br/>leser: kartleggingen, aldri koden<br/>skriver: forsvarsplanen<br/>hver utbedring peker p\xe5 noe detect faktisk kartla"]\n    harden["4 \xb7 harden (utbedring)<br/>leser: forsvarsplanen, og koden den ber\xf8rer<br/>skriver: koden, og herdingsloggen<br/>den eneste fasen som endrer kode, \xe9n utbedring om gangen, den minste endringen som holder"]\n    verify["5 \xb7 verify (verifisering)<br/>leser: koden, og herdingsloggen<br/>skriver: hver \xe5pen konklusjon i herdingsloggen<br/>koden holdt opp mot loggen, statisk, aldri myket opp"]\n    charter --\x3e detect --\x3e plan --\x3e harden --\x3e verify\n    verify -.->|"avvist: gjen\xe5pnet arbeid for harden,<br/>tatt i bruk p\xe5 nytt ut fra den registrerte begrunnelsen"| harden\n    verify -.->|"lukking: tar det den beviste lukket<br/>ut av hele kjeden,<br/>\xe9n linje i historikken"| detect\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figur 1."})," Flyten i fem faser: hva hver fase leser, hva den skriver, og den b\xe6rende invarianten. Verify styrer begge returene: Et avvist sikringstiltak gjen\xe5pner harden, og et funn som er bevist lukket, tas ut av hele kjeden, med \xe9n linje i historikken."]}),"\n",(0,s.jsx)(n.p,{children:"Ansvarsdelingen er bidraget. Fordi hver fase har \xe9n oppgave, holdes en feil til ett sted, og leseren kan stole p\xe5 det hver artefakt hevder."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Kjerneinnsikt"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Applied er ikke verifisert:"}),' Harden registrerer at en utbedring er tatt i bruk. Verify verifiserer den ved \xe5 holde koden opp mot den registreringen, og konklusjonen mykes aldri opp for \xe5 passe loggen. Et sikringstiltak kan finnes i koden og likevel la risikoen v\xe6re n\xe5bar, og da er den \xe6rlige konklusjonen "Risk not closed".']}),"\n"]}),"\n",(0,s.jsx)(n.h3,{id:"charter-retningslinjer",children:"charter (retningslinjer)"}),"\n",(0,s.jsxs)(n.p,{children:["Fasen charter fastsetter sikkerhetsprinsippene for prosjektet, reglene hver senere fase m\xe5 respektere. Det er det overordnede laget, en slags kompileringstidskontroll for sikkerhetsniv\xe5et i prosjektet. Hvert prinsipp har et tydelig navn, en ufravikelig regel som kan kontrolleres mot koden, og en linje ",(0,s.jsx)(n.code,{children:"Why:"})," som oppgir risikoen det forebygger, ikke bare utbedringen. Fasen leser alltid selve prosjektet (manifestene, strukturen og avhengighetene), og en beskrivelse fra brukeren, n\xe5r den gis, er en retning som lesingen deretter utvider ut over det brukeren nevnte. Uten beskrivelse er prosjektet den eneste kilden. De to legges sammen i stedet for \xe5 konkurrere, og sikkerhetsprinsippene registrerer retningslinjene prosjektet b\xf8r f\xf8lge, ikke tilstanden i koden. En ikke-utvikler skal kunne lese dem og forst\xe5 b\xe5de regelen og risikoen."]}),"\n",(0,s.jsx)(n.h3,{id:"detect-oppdagelse",children:"detect (oppdagelse)"}),"\n",(0,s.jsxs)(n.p,{children:['Detect leser koden og kartlegger det systemet faktisk gj\xf8r som har sikkerhetsmessig betydning. Den styrende instruksen er "oppdage, ikke finne p\xe5": Registrer bare det koden underbygger, med belegget de senere fasene trenger. Detect er n\xf8ytral. Den tvinger ikke funnene sine til \xe5 passe sikkerhetsprinsippene, fordi det \xe5 holde risikoer opp mot reglene i sikkerhetsprinsippene er jobben til fasen plan. Hvert funn har tre deler: hva det er (en beskrivelse i et enkelt spr\xe5k), hvorfor det betyr noe (risikoen, ikke bare faktumet) og belegget (funksjonen eller ruten der det ligger). Belegget inneholder ingen filsti. Stien ligger bare i sporingskartet (',(0,s.jsx)(n.code,{children:"\xa7XI"}),"), s\xe5 teksten inneholder aldri en sti som kan bli utdatert."]}),"\n",(0,s.jsx)(n.h3,{id:"plan-triage",children:"plan (triage)"}),"\n",(0,s.jsx)(n.p,{children:"Plan gj\xf8r hvert funn om til en utbedring, navngitt etter risikoklassen (med henvisning til de etablerte referansene, CWE og OWASP, der de underbygger den) og knyttet til sikkerhetsprinsippet utbedringen ivaretar. Prioriteten (kritisk, h\xf8y, middels, lav) er ikke et fritt valg: Plan vurderer hvert funn med CVSS v4.0 og metrikkene Base og Environmental, s\xe5 niv\xe5et er scoren uttrykt med vanlige ord, begrunnet med \xe9n linje i et enkelt spr\xe5k om eksponering og hva som st\xe5r p\xe5 spill, og to kj\xf8ringer gir samme rekkef\xf8lge. Vektoren er det presise ankeret for en ekspert, niv\xe5et og begrunnelsen den samme vurderingen i en form alle kan f\xf8lge. Plan arbeider bare ut fra kartleggingen og leser aldri koden. Dette er en bevisst begrensning, ikke en svakhet: Den tvinger hver utbedring til \xe5 peke p\xe5 noe detect faktisk oppdaget. Hvis et omfang aldri ble kartlagt, stopper plan og sender brukeren tilbake til detect i stedet for \xe5 gjette."}),"\n",(0,s.jsx)(n.h3,{id:"harden-utbedring",children:"harden (utbedring)"}),"\n",(0,s.jsx)(n.p,{children:'Harden er den eneste fasen som endrer kode, s\xe5 den g\xe5r forsiktig frem. Om en endring trenger brukerens godkjenning, avgj\xf8res av agenten og tillatelsesmodusen den kj\xf8rer i, s\xe5 harden legger ikke til noe eget bekreftelsestrinn. Den tar i bruk \xe9n utbedring om gangen, avhengighetene f\xf8rst og deretter h\xf8yeste prioritet, slik at hver endring forblir liten, lett \xe5 gjennomg\xe5 og lett \xe5 angre. Den svekker aldri et eksisterende sikringstiltak for \xe5 f\xe5 en ny utbedring til \xe5 passe, og den bryter aldri et sikkerhetsprinsipp. Hvis en utbedring ville komme i konflikt med et prinsipp, stopper harden og viser konflikten i stedet for \xe5 ta den i bruk. Hver blokk registreres som Applied, Partial eller Blocked. "Applied betyr ikke at den er verifisert enn\xe5", og det er dette den neste fasen h\xe5ndterer.'}),"\n",(0,s.jsx)(n.h3,{id:"verify-verifisering",children:"verify (verifisering)"}),"\n",(0,s.jsx)(n.p,{children:'Verify verifiserer hvert sikringstiltak som er tatt i bruk, ved \xe5 lese koden og holde den opp mot det harden registrerte. Verifiseringen er nettopp dette, koden holdt opp mot loggen, og den er statisk: Den bekrefter at et sikringstiltak finnes og er korrekt i koden, ikke at det holder under angrep p\xe5 et kj\xf8rende system. Den kontrollen under kj\xf8ring, den typen som utf\xf8rer ekte eller simulerte angrep mot det kj\xf8rende systemet, er bevisst utenfor omfanget. Verify gir \xe9n av tre konklusjoner: Risk closed, Risk not closed eller Cannot tell from the code. Den lager ingen egen artefakt: Harden og verify deler herdingsloggen, der harden eier det som ble gjort og verify eier konklusjonen og begrunnelsen, og ingen av dem skriver noen gang i den andres felt. Et avvist sikringstiltak er gjen\xe5pnet arbeid for harden, som ved neste kj\xf8ring lar konklusjonen g\xe5 foran sin egen lesning av koden og tar utbedringen i bruk p\xe5 nytt mot n\xf8yaktig det gapet begrunnelsen peker p\xe5. Verify stoler mer p\xe5 koden enn p\xe5 loggen, fordi en logg kan p\xe5st\xe5 mer enn koden leverer. Den har bare lesetilgang til koden til brukeren, og den myker aldri opp en konklusjon for \xe5 passe loggen. Et sikringstiltak kan finnes og likevel la risikoen v\xe6re n\xe5bar p\xe5 en annen m\xe5te, og da er den \xe6rlige konklusjonen "Risk not closed". Hvis verify under lesingen legger merke til et sikkerhetsproblem kartleggingen aldri dekket, finner den ikke p\xe5 en konklusjon for det, fordi oppdagelse er jobben til detect: Den melder fra om problemet og sender brukeren tilbake til detect, slik at funnet kommer inn gjennom den samme flyten i stedet for \xe5 g\xe5 utenom den.'}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Gjennomg\xe5ende eksempel: filopplasting."})," Ett enkelt funn viser hele ryggraden fra start til slutt."]}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"detect"})," finner det: Systemet tar imot filer fra brukere, og opplastingshandleren stoler p\xe5 MIME-typen klienten sender, uten \xe5 sjekke den faktiske filtypen. ",(0,s.jsx)(n.em,{children:"Hvorfor det betyr noe:"})," En fil forkledd som et bilde kan skjule ondsinnet kode."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"plan"})," bestemmer utbedringen, prioritet ",(0,s.jsx)(n.strong,{children:"kritisk"}),', i tr\xe5d med prinsippet "Alle inndata er ikke-klarerte til de er validert": Sjekk den faktiske filtypen og st\xf8rrelsen, gi filen nytt navn ved lagring, og lagre opplastinger der de ikke kan kj\xf8res som kode.']}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"harden"})," tar den i bruk, status ",(0,s.jsx)(n.strong,{children:"Applied"}),": Handleren oppdager n\xe5 den faktiske typen ut fra innholdet, h\xe5ndhever en st\xf8rrelsesgrense, avviser alt uventet, gir nytt navn ved lagring og lagrer der kode ikke kan kj\xf8res."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"verify"})," leser handleren, holder den opp mot loggen og returnerer ",(0,s.jsx)(n.strong,{children:"Risk closed"}),": Koden gj\xf8r n\xf8yaktig det loggen hevder."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:["Det samme funnavnet g\xe5r gjennom kartleggingen, forsvarsplanen og herdingsloggen, og verify handler p\xe5 den loggen under det samme navnet: En \xe5pen konklusjon skrives i blokken til funnet, og et funn som er bevist lukket, tas ut (",(0,s.jsx)(n.code,{children:"\xa7V"}),"). Det felles navnet er identiteten (",(0,s.jsx)(n.code,{children:"\xa7XI"}),")."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"v-lukkbarhet-et-funn-har-en-sluttilstand",children:"V. Lukkbarhet: et funn har en sluttilstand"}),"\n",(0,s.jsxs)(n.p,{children:["De fleste sikkerhetsverkt\xf8y etterlater brukeren med et etterslep som bare vokser. SDH inntar et annet standpunkt: ",(0,s.jsx)(n.strong,{children:"Et funn er lukkbart, s\xe5 det har en sluttilstand i stedet for \xe5 leve i et endel\xf8st etterslep"})," (figur 2). Dette f\xf8lger direkte av prinsippet om avstemming."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Lukkbarhet:"})," En risiko som er verifisert lukket, tas ut av hele flyten, slik at funnet kommer til ro og \xe5pnes igjen f\xf8rst n\xe5r koden endres. Et funn har en sluttilstand, selv om selve sikkerhetsprogrammet fortsetter kontinuerlig."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Artefaktene i SDH er levende dokumenter, ikke logger. Hver gang en fase kj\xf8res p\xe5 nytt, sjekker den hver eksisterende oppf\xf8ring mot den n\xe5v\xe6rende sannheten og gj\xf8r \xe9n av tre ting: Den beholder det som fortsatt holder, skriver om det som er endret, eller fjerner det som ikke lenger gjelder. Et funn som koden viser at n\xe5 er l\xf8st, fjernes ganske enkelt. Arbeidsdokumentasjonen gjenspeiler n\xe5tiden, ikke fortiden."}),"\n",(0,s.jsx)(n.p,{children:"Lukking er den samme avstemmingen, f\xf8rt helt til ende. N\xe5r verify verifiserer at en risiko er lukket, tar den funnet ut av hele flyten: kartleggingen, forsvarsplanen, herdingsloggen og sporingskartet. Det er derfor verify er den ene fasen som skriver til artefaktene til de andre fasene: Den er fasen som lukker sl\xf8yfen. N\xe5r funnet forlater kjeden, destillerer uttaket det til en kort oppf\xf8ring i en historikk som ligger utenfor arbeidskjeden og aldri behandles p\xe5 nytt. Dette er skillet mellom \xe5 forsvinne og \xe5 lukkes: Et funn som avstemmingen fjernet fordi det sluttet \xe5 v\xe6re sant, etterlater ingenting, mens et funn som er bevist lukket, gj\xf8r seg fortjent til sin linje i historikken. Et funn som er tatt ut, mangler i hver arbeidsartefakt etterp\xe5, og det frav\xe6ret er forventet, ikke en brutt kjede."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:"stateDiagram-v2\n    direction TB\n    [*] --\x3e OPEN: detect oppdager\n    OPEN --\x3e Plan: plan\n    Plan --\x3e Harden: harden\n    Harden --\x3e Verify: verify\n    Verify --\x3e StoodDown: Risk closed\n    StoodDown --\x3e SETTLED\n    SETTLED --\x3e OPEN: kodeendringer gjen\xe5pner et funn\n    Plan: plan\n    Harden: harden\n    Verify: verify\n    StoodDown: STOOD DOWN \xb7 \xe9n linje i historikken\n"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figur 2."})," Tilstandsmaskinen for lukkbarhet. Et funn g\xe5r gjennom OPEN \u2192 STOOD DOWN \u2192 SETTLED og \xe5pnes igjen f\xf8rst n\xe5r koden endres."]}),"\n",(0,s.jsx)(n.p,{children:"N\xe5r alt innenfor omfanget er tatt ut, er syklusen i ro, og tilstanden i ro har en konkret form: En artefakt der det siste funnet ble lukket, fjernes helt, s\xe5 en helt lukket kjede etterlater bare sikkerhetsprinsippene og historikken, retningslinjene og beviset. Syklusen \xe5pnes igjen f\xf8rst n\xe5r koden endres. Metodikken gir hvert funn en tydelig slutt, og det er nettopp det et endel\xf8st etterslep ikke kan."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"vi-dualiteten-som-utvider-utviklerens-kunnskap",children:"VI. Dualiteten som utvider utviklerens kunnskap"}),"\n",(0,s.jsxs)(n.p,{children:["SDH erstatter ikke mennesker, og den erstatter ikke spesialiserte Blue Team-verkt\xf8y. Den ",(0,s.jsx)(n.strong,{children:"utvider utviklerens egen kunnskap"}),". Jo mer en utvikler forst\xe5r av sikkerhet, desto mer presist kan vedkommende styre flyten, og desto mer selvstendighet f\xe5r vedkommende. En utvikler som forst\xe5r lite, f\xe5r likevel et sikkert resultat, fordi den automatiske modusen beskytter vedkommende."]}),"\n",(0,s.jsxs)(n.p,{children:["Inversjonen fra ",(0,s.jsx)(n.code,{children:"\xa7I"}),", at sikkerhetskunnskapen ligger i spesifikasjonen, virker i begge retninger. For nybegynneren er den beskyttelse: Nybegynneren trenger ikke \xe5 vite hva det skal sp\xf8rres om, fordi spesifikasjonen kommer med forslag. For eksperten er den forsterkning: Den samme spesifikasjonen lar eksperten sikte flyten presist i stedet for \xe5 jobbe mot en fast sjekkliste."]}),"\n",(0,s.jsx)(n.p,{children:"Hver fase b\xe6rer denne dualiteten i sin egen virkem\xe5te (figur 3). Kj\xf8res fasen uten inndata, handler den p\xe5 hele omfanget p\xe5 vegne av brukeren. F\xe5r den en retning, snevrer den samme fasen seg inn til n\xf8yaktig det brukeren siktet den mot."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    inversion["\xe9n inversjon, to retninger:<br/>sikkerhetskunnskapen ligger i spesifikasjonen"]\n    inversion --\x3e auto["automatisk modus (ingen inndata)<br/>fasen foresl\xe5r og handler<br/>p\xe5 hele omfanget"]\n    inversion --\x3e directed["styrt modus (inndata gitt)<br/>fasen snevrer seg inn til n\xf8yaktig<br/>det brukeren siktet den mot"]\n    auto --\x3e novice["nybegynneren, beskyttet:<br/>et sikkert resultat uten \xe5<br/>vite hva det skal sp\xf8rres om"]\n    directed --\x3e expert["eksperten, forsterket:<br/>flyten siktet presist,<br/>ikke en fast sjekkliste"]\n    novice -.-> phases["de samme fem fasene tjener begge:<br/>charter \xb7 detect \xb7 plan \xb7 harden \xb7 verify"]\n    expert -.-> phases\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figur 3."})," Dualiteten som utvider utviklerens kunnskap. \xc9n inversjon tjener to m\xe5lgrupper: Den automatiske modusen beskytter nybegynneren, og den styrte modusen forsterker eksperten, gjennom de samme fem fasene."]}),"\n",(0,s.jsxs)(n.p,{children:["Spesialiseringene som lastes ved behov (",(0,s.jsx)(n.code,{children:"\xa7VII"}),'), gj\xf8r dualiteten eksplisitt i sin egen tekst. Hver av dem forteller agenten at kunnskapen "utvider din vurdering", og at den skal fortsette \xe5 resonnere ut over det spesialiseringen gir. Kunnskapen er et gulv, ikke et tak. Det er dette som tjener begge m\xe5lgruppene i den balansen dokumentet sikter mot: Utviklermilj\xf8et f\xe5r et betydelig instrument, og Blue Team-praktikeren f\xe5r en strukturert b\xe6rer som ikke later som den gj\xf8r jobben for vedkommende.']}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"vii-ikke-kallbare-spesialiseringer-og-prompt-on-demand",children:"VII. Ikke-kallbare spesialiseringer og prompt-on-demand"}),"\n",(0,s.jsxs)(n.p,{children:["Dette er det mest nyskapende m\xf8nsteret i metodikken. SDH b\xe6rer fokusert sikkerhetskunnskap som spesialiseringer som ",(0,s.jsx)(n.strong,{children:"bare lastes ved behov"}),", og agenten avgj\xf8r selv hvilke som skal lastes ved \xe5 matche konteksten i prosjektet. Vi kaller dette ",(0,s.jsx)(n.strong,{children:"prompt-on-demand"}),": en m\xe5te for agenten \xe5 velge hvilken kunnskap som skal aktiveres ut fra omfanget av prosjektet den er i, i stedet for \xe5 kj\xf8re hver kontroll som standard. Spesialiseringene er i stadig utvikling, og hvilken som helst av dem kan endres eller erstattes n\xe5r som helst. Bidraget er m\xf8nsteret, ikke spesialiseringene i seg selv."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Prompt-on-demand:"})," Agenten velger hvilken sikkerhetskunnskap som skal aktiveres ved \xe5 matche den mot omfanget av prosjektet foran seg, slik at den relevante kunnskapen hentes inn ut fra hva prosjektet faktisk er, i stedet for at hver kontroll kj\xf8rer som standard."]}),"\n"]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Ikke-kallbar spesialisering:"})," En fokusert, spr\xe5kuavhengig enhet med sikkerhetskunnskap for \xe9n kontekst, som filopplasting eller kode som kj\xf8rer i nettleseren. Den reviderer og forklarer, skriver aldri om kode og lager aldri angrepsinndata. Den er ikke en kommando: Den lastes n\xe5r konteksten den dekker, er innenfor omfanget, eller n\xe5r en prompt ber om den ved navn."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Hver spesialisering navngir de tryggere formene for risikoene den dekker, og forteller agenten hvordan den skal handle p\xe5 et funn i hver fase som bruker den: hvordan funnet skal vurderes under oppdagelsen, hvordan utbedringen tas trygt i bruk under utbedringen, og hvordan den bevises under verifiseringen."}),"\n",(0,s.jsxs)(n.p,{children:["Det definerende trekket er at en spesialisering ",(0,s.jsx)(n.strong,{children:"ikke kan kalles p\xe5 egen h\xe5nd"}),": Den er ikke en kommando, og inne i flyten er det et treff som laster den. Oppdagelsesfasen lister katalogen \xe9n gang, matcher konteksten i prosjektet mot det hver oppf\xf8ring dekker, og laster bare spesialiseringene hvis kontekst finnes innenfor omfanget. De senere fasene gjenbruker den matchede listen i stedet for \xe5 liste p\xe5 nytt, s\xe5 \xe9n matching tjener hele kjeden, og den forebyggende modusen (",(0,s.jsx)(n.code,{children:"\xa7IX"}),") kj\xf8rer den samme matchingen mot arbeidet som skal bygges. En spesialisering hvis kontekst mangler, hoppes over, og det \xe5 hoppe over er like etterpr\xf8vbart som \xe5 laste: Hver oppf\xf8ring i katalogen f\xe5r en eksplisitt konklusjon, tatt i bruk eller hoppet over, med begrunnelsen lest ut av koden, s\xe5 en vag f\xf8lelse av irrelevans aldri erstatter faktisk frav\xe6r. \xc5 ikke finne noen som gjelder, er et gyldig utfall."]}),"\n",(0,s.jsxs)(n.p,{children:["Katalogen er data, og vekst er \xe9n kunnskapsfil pluss \xe9n katalograd, aldri en ny kommando. De innebygde spesialiseringene er gruppert i kategorier, som OWASP, et spr\xe5k eller KI-integrasjoner, og katalogen et prosjekt bruker, inneholder de innebygde fra kategoriene det valgte pluss prosjektets egne spesialiseringer. Prosjektet registrerer det valget sammen med resten av tilstanden sin, s\xe5 et helt team matcher mot den samme katalogen. Dette er det samme kontekstbevisste prinsippet som i fasene, brukt p\xe5 kunnskap: Den relevante kunnskapen hentes inn ut fra hva prosjektet faktisk er, i stedet for at hver kontroll kj\xf8rer som standard. Den samme egenskapen lar brukeren, ikke bare vedlikeholderen, utvide katalogen: En sikkerhetskilde eller et tema brukeren gir, destilleres til en ny spesialisering som tilh\xf8rer prosjektet, blir med i katalogen uansett kategorier og lastes n\xf8yaktig som en innebygd, og den overstyrer den innebygde med samme navn. \xc5 skrive en spesialisering er i seg selv kun defensivt og f\xf8lger den samme grensen spesialiseringene h\xe5ndhever: En beskrivelse av et angrep kan v\xe6re kilden, men spesialiseringen den gir, reviderer og forklarer og lager aldri en fungerende exploit. Slik strekker inversjonen fra ",(0,s.jsx)(n.code,{children:"\xa7I"}),", at intelligensen ligger i spesifikasjonen, seg til selve katalogen, som brukeren kan utdype for sin egen kontekst uten \xe5 skrive kode."]}),"\n",(0,s.jsx)(n.p,{children:"Et kort eksempel illustrerer prompt-on-demand. Detect leser en mappe med kode som kj\xf8rer i nettleseren. Den matcher den konteksten i katalogen, laster spesialiseringen som dekker den, og viser et funn p\xe5 klientsiden gjennom de vanlige stegene i detect. Spesialiseringene hvis kontekst mangler i dette omfanget, gir ikke treff, s\xe5 de lastes aldri, og hver av dem registreres som hoppet over. Det var prosjektet som avgjorde hvilken kunnskap som var relevant, ikke en fast konfigurasjon."}),"\n",(0,s.jsxs)(n.p,{children:["Determinisme dukker opp nettopp der den betyr noe. En spesialisering kan ha en deterministisk kontroll, ikke bare tekst: Der en risikoklasse har en skarp beslutningsprosedyre, returnerer et lite program en fast konklusjon for en gitt verdi, for eksempel et lite sett ord som ",(0,s.jsx)(n.code,{children:"safe"}),", ",(0,s.jsx)(n.code,{children:"unsafe"})," eller ",(0,s.jsx)(n.code,{children:"invalid input"}),". Noen risikoklasser kan avgj\xf8res deterministisk p\xe5 nettopp denne m\xe5ten, med et etablert fagarbeid bak beslutningsprosedyren ",(0,s.jsx)(n.code,{children:"[9]"}),", ",(0,s.jsx)(n.code,{children:"[10]"}),", ",(0,s.jsx)(n.code,{children:"[11]"}),". Kontrollen vurderer enten kandidater agenten leverer, eller skanner omfanget for \xe5 finne dem selv, og i begge tilfeller er det kontrollen, ikke agenten, som returnerer konklusjonen. En spesialisering som er universell nok, kan merkes som p\xe5krevd i katalogen og tas da alltid i bruk, med kontrollen kj\xf8rt over hele omfanget. Dette er det ene tilfellet der kunnskap lastes uten et konteksttreff, og det deklareres i dataene i katalogen, aldri avgjort av agenten der og da. Det er her SDH forankrer agentens resonnering i noe repeterbart, uten \xe5 late som hele flyten er deterministisk."]}),"\n",(0,s.jsxs)(n.p,{children:["Til slutt er spesialiseringene ",(0,s.jsx)(n.strong,{children:"l\xf8srivbare"}),". Fordi kunnskapen st\xe5r p\xe5 egne ben, kan en bruker kj\xf8re en av dem direkte i en prompt som ikke har noe med hele SDH-flyten \xe5 gj\xf8re, og holde sikkerheten med i vanlig utvikling. En spesialisering med en deterministisk kontroll kan for eksempel sjekke hver kandidat som produseres under vanlig koding og bare beholde de trygge. Denne l\xf8srivbarheten er en del av grunnen til at SDH tilpasser seg s\xe5 mange situasjoner, som er temaet for ",(0,s.jsx)(n.code,{children:"\xa7VIII"}),", og det fulle uttrykket for den er den forebyggende modusen (",(0,s.jsx)(n.code,{children:"\xa7IX"}),"), der den samme kunnskapen vokter vanlig utvikling fra start til slutt."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"viii-tilstandsuavhengighet-og-ikke-autoritativ-tilpasningsevne",children:"VIII. Tilstandsuavhengighet og ikke-autoritativ tilpasningsevne"}),"\n",(0,s.jsx)(n.p,{children:"To egenskaper skiller SDH fra rigide spec-metodikker."}),"\n",(0,s.jsx)(n.h3,{id:"tilstandsuavhengighet",children:"Tilstandsuavhengighet"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tilstandsuavhengighet:"})," Metodikken er ikke avhengig av utviklingstilstanden. Den passer til en tom mappe, et prosjekt under arbeid, \xe9n enkelt pull request eller en stor eldre kodebase, i hvilken som helst stack, fordi den l\xe6rer utgangspunktet ved \xe5 lese det."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Hver fase fungerer likt enten prosjektet er helt nytt eller allerede finnes. Fasen charter utleder prinsipper fra den koden som finnes. Detect kartlegger den koden som er der, selv om det er sv\xe6rt lite. Det finnes ikke noe forutsatt utgangspunkt."}),"\n",(0,s.jsx)(n.h3,{id:"ikke-autoritativ-tilpasningsevne",children:"Ikke-autoritativ tilpasningsevne"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Ikke-autoritativ tilpasningsevne:"})," Metodikken tilpasser seg scenarioet i stedet for \xe5 p\xe5tvinge et fast omfang brukeren m\xe5 f\xf8lge. N\xe5r brukeren ikke vet hva som skal sies, leser den milj\xf8et den ble kalt i, skaper kontekst og stiller sp\xf8rsm\xe5lene som former hva den gj\xf8r videre."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Forslagsmodusen i fasen charter er det tydeligste eksempelet: SDH utleder sikkerhetsprinsipper som er sikre som standard, ved \xe5 analysere prosjektet, sp\xf8r brukeren bare n\xe5r et hull faktisk endrer resultatet, skriver dem deretter og presenterer hvert prinsipp i et enkelt spr\xe5k med risikoen det forebygger. Sikkerhetsprinsippene er et levende dokument brukeren omarbeider ved \xe5 kj\xf8re fasen p\xe5 nytt, ikke en kontrakt l\xe5st bak en godkjenningsforesp\xf8rsel, s\xe5 brukeren trenger aldri \xe5 vite hva det skal sp\xf8rres om."}),"\n",(0,s.jsx)(n.p,{children:"Denne tilpasningsevnen viser seg som en f\xf8lsomhet for formen p\xe5 inndataene: Den samme fasen leser det den fikk, og velger en modus (figur 4). En fil i prompten, et funn fra listen, en bekymring, et fokusert oppdrag mot et kjent svakt punkt eller en foresp\xf8rsel om en full brute force-gjennomgang: Hver av dem passer brukerens behov, fordi flyten er ikke-autoritativ av design. Ingenting av dette svekker grunnlaget som er sikkert som standard. Fleksibilitet former hvordan grunnlaget brukes, den senker det aldri."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    shape["fasen leser formen<br/>p\xe5 det den fikk"]\n    shape --\x3e none["ingen inndata"]\n    shape --\x3e paths["\xe9n eller flere stier"]\n    shape --\x3e concern["en beskrevet problemstilling"]\n    shape --\x3e finding["et navngitt funn"]\n    shape --\x3e band["et prioritetsniv\xe5"]\n    none --\x3e auto["den automatiske modusen:<br/>foresl\xe5, eller skann<br/>hele omfanget"]\n    paths --\x3e focus["fokuser bare p\xe5 de<br/>filene eller mappene"]\n    concern --\x3e scoped["avgrens til den<br/>ene problemstillingen"]\n    finding --\x3e item["handle p\xe5 det ene<br/>sporede elementet"]\n    band --\x3e priority["handle bare p\xe5 kritisk,<br/>h\xf8y, middels eller lav"]\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figur 4."})," Ikke-autoritativ tilpasningsevne. Den samme fasen leser formen p\xe5 inndataene og velger en modus, s\xe5 omfanget er alltid brukerens, aldri p\xe5tvunget."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ix-den-universelle-forebyggende-modusen-det-samme-forsvaret-mens-arbeidet-bygges",children:"IX. Den universelle forebyggende modusen: det samme forsvaret mens arbeidet bygges"}),"\n",(0,s.jsx)(n.p,{children:"SDH har \xe9n utfyllende modus: vanlig utvikling utf\xf8rt med det samme forsvaret aktivt mens koden skrives. Brukeren ber om selve arbeidet, en innloggingsside, en opplasting, et endepunkt, og metodikken vokter byggingen mens den skjer, s\xe5 resultatet er sikkert som standard i det \xf8yeblikket det lander, i stedet for etter en senere herdingsrunde."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Den forebyggende modusen:"})," vanlig utvikling kj\xf8rt under det overordnede laget og kunnskapen i SDH. Sikkerhetsprinsippene binder byggingen, spesialiseringene som er relevante for det som skal lages, lastes ved behov, og resultatet holdes opp mot n\xf8yaktig det forsvaret som ble brukt, f\xf8r arbeidet regnes som ferdig."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:["Modusen gjenbruker hver del fasene allerede har, rettet mot kode som ikke finnes enn\xe5. Kontekstoppdagelsen flyttes fra koden til intensjonen: Agenten resonnerer seg gjennom det den skal til \xe5 bygge og grensene det arbeidet krysser (en innlogging inneb\xe6rer p\xe5loggingsdetaljer, en \xf8kt og inndata utenfra), og det er den resonneringen kunnskapskatalogen matches mot. Prompt-on-demand (",(0,s.jsx)(n.code,{children:"\xa7VII"}),") generaliseres her: Kontekst kan oppdages i planen for kode, ikke bare i kode som finnes. Sikkerhetsprinsippene styrer som alltid, og en foresp\xf8rsel som ville bryte et prinsipp, vises som en konflikt og bygges aldri. Forsvaret brukes underveis, i det \xf8yeblikket hver del skrives, med validering ved grensen og den trygge konstruksjonen valgt f\xf8rste gang, s\xe5 en versjon som fungerer, men er usikker, aldri finnes og trenger \xe5 rettes."]}),"\n",(0,s.jsx)(n.p,{children:"Modusen slutter slik verify begynner. F\xf8r arbeidet regnes som ferdig, holder den som bygger, sitt eget resultat opp mot forsvaret den brukte: Sikringstiltaket m\xe5 ligge p\xe5 risikoens vei, ikke ved siden av den, det m\xe5 v\xe6re komplett, og der en spesialisering har en deterministisk kontroll, g\xe5r kontrollens konklusjon foran agentens egen lesning. Et hull som blir funnet her, lukkes som en del av det samme arbeidet, fordi \xe5 gj\xf8re arbeidet ferdig betyr \xe5 gj\xf8re det ferdig p\xe5 en sikker m\xe5te."}),"\n",(0,s.jsxs)(n.p,{children:["Det modusen avviser, er like bevisst som det den gj\xf8r. Den bygger bare det som ble bedt om, og reviderer ingenting rundt det: \xc5 revidere det som finnes, h\xf8rer til fasene. Den skriver ingen artefakt og sporer ingen funn, fordi et funn er en risiko oppdaget i det som finnes, og form\xe5let med denne modusen er at den usikre versjonen aldri lander i det hele tatt. De to retningene utfyller hverandre: Fasene lukker det som allerede er der (",(0,s.jsx)(n.code,{children:"\xa7V"}),"), og den forebyggende modusen hindrer nytt arbeid i \xe5 gjen\xe5pne det. En kjede i ro forblir i ro, ikke fordi utviklingen stoppet, men fordi det som bygges mens den er i ro, bygges med forsvaret p\xe5 plass."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"x-security-driven-hardening-versus-spec-driven-development",children:"X. Security-Driven Hardening versus Spec-Driven Development"}),"\n",(0,s.jsxs)(n.p,{children:["Security-Driven Hardening (SDH) vokste ut av grunnlaget i Spec-Driven Development (SDD) og skilte deretter tydelig lag med det. Den strukturelle arven er reell og anerkjent: spec-first, agentdrevet, et styrende dokument og et sett kommandoer i faser som agenten kj\xf8rer. SDH gjenbruker den strukturen bevisst. Det som skiller seg, er form\xe5let, autoritetsmodellen, den forutsatte tilstanden og sluttbetingelsen. Vi behandler SDD som en klasse og bruker rapporten til Piskala ",(0,s.jsx)(n.code,{children:"[1]"})," som den kanoniske formuleringen av metodikken, Spec Kit fra GitHub ",(0,s.jsx)(n.code,{children:"[2]"})," som det kanoniske agentverkt\xf8ysettet og OpenSpec ",(0,s.jsx)(n.code,{children:"[3]"})," som et annet verkt\xf8y fra samme familie."]}),"\n",(0,s.jsxs)(n.p,{children:["SDD snur tradisjonell utvikling p\xe5 hodet ved \xe5 gj\xf8re spesifikasjoner kj\xf8rbare: Spesifikasjonen genererer direkte en fungerende implementasjon i stedet for bare \xe5 veilede den ",(0,s.jsx)(n.code,{children:"[1]"}),". Fasesettet driver et bygg fremover ",(0,s.jsx)(n.code,{children:"[2]"})," (fastsett styrende prinsipper, spesifiser hva som skal bygges, planlegg teknologistakken, del planen opp i oppgaver og implementer). Det styrende dokumentet, en konstitusjon av prinsipper, er grunnsteinen agenten m\xe5 f\xf8lge hele veien. Det er kjernen i forskjellen. I SDD flyter autoriteten fra spesifikasjonen inn i byggingen, og implementasjonen forventes \xe5 f\xf8lge den."]}),"\n",(0,s.jsx)(n.p,{children:"SDH snur nesten hver akse i den kontrakten (tabell 3)."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Kjerneinnsikt"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Kjerneforskjellen:"})," I SDD flyter autoriteten fra spesifikasjonen inn i byggingen, og implementasjonen forventes \xe5 f\xf8lge den. SDH er ikke-autoritativ og flyter motsatt vei, innover fra den oppdagede konteksten til systemet, og herder det som allerede er der."]}),"\n"]}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Akse"}),(0,s.jsx)(n.th,{children:"SDD"}),(0,s.jsx)(n.th,{children:"SDH"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"M\xe5l"}),(0,s.jsx)(n.td,{children:"Levere funksjoner. Spesifikasjonen blir en fungerende implementasjon."}),(0,s.jsx)(n.td,{children:"Herde det som finnes eller bygges. Hver fase er rammet inn for forsvar."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Autoritetsmodell"}),(0,s.jsx)(n.td,{children:"Autoritativ. Spesifikasjonen og konstitusjonen begrenser byggingen til et omfang den m\xe5 f\xf8lge."}),(0,s.jsx)(n.td,{children:"Ikke-autoritativ. SDH tilpasser seg scenarioet, og brukeren kan omformulere, droppe eller snevre inn."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Forutsatt tilstand"}),(0,s.jsx)(n.td,{children:"Et bygg fremover fra en spesifikasjon."}),(0,s.jsx)(n.td,{children:"Tilstandsuavhengig: tom mappe, prosjekt under arbeid, \xe9n enkelt PR eller eldre kode."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Sluttbetingelse"}),(0,s.jsx)(n.td,{children:"Slutter n\xe5r funksjonen er bygget."}),(0,s.jsx)(n.td,{children:"Lukkbar. Et funn kommer til ro og \xe5pnes igjen f\xf8rst n\xe5r koden endres."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Styrende dokument"}),(0,s.jsx)(n.td,{children:"En konstitusjon av prinsipper agenten m\xe5 f\xf8lge."}),(0,s.jsxs)(n.td,{children:["Sikkerhetsprinsipper rammet inn rundt risiko (hvert har en linje ",(0,s.jsx)(n.code,{children:"Why:"}),"), uttrykkelig ikke en fast kontrakt."]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Hvordan kunnskapen vokser"}),(0,s.jsx)(n.td,{children:"Legg til en kommando (eller utvid fasesettet)."}),(0,s.jsx)(n.td,{children:"Legg til en ikke-kallbar spesialisering agenten laster ved behov: \xe9n fil pluss \xe9n katalograd, ingen ny kommando."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Hvem den tjener"}),(0,s.jsx)(n.td,{children:"En utvikler som driver en funksjon fremover."}),(0,s.jsx)(n.td,{children:"Enhver bruker, utvikler eller ikke, gjennom den samme flyten."})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Hva som endrer kode"}),(0,s.jsx)(n.td,{children:"Implementasjonsfasen genererer byggingen."}),(0,s.jsx)(n.td,{children:"Bare fasen harden endrer kode, \xe9n utbedring om gangen."})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tabell 3."})," SDD versus SDH langs \xe5tte akser. L\xe5nt struktur, snudd kontrakt."]}),"\n",(0,s.jsxs)(n.p,{children:["For \xe5 yte slekten rettferdighet: SDD er velpr\xf8vd forgjengerarbeid, og SDH skylder den strukturen den kj\xf8rer p\xe5. Avviket er ikke en kritikk av SDD, som l\xf8ser et annet problem (\xe5 bygge fremover) godt. SDH tar det samme velpr\xf8vde maskineriet og retter det mot forsvar, tilpasningsevne og lukking. OpenSpec ",(0,s.jsx)(n.code,{children:"[3]"}),", organisert rundt endringsforslag, oppgavelister og spesifikasjoner per endring, bekrefter m\xf8nsteret: Familien driver et bygg fremover fra en spesifikasjon, mens SDH herder et system innover fra den oppdagede konteksten. Selv den forebyggende modusen i SDH (",(0,s.jsx)(n.code,{children:"\xa7IX"}),"), det ene stedet den f\xf8lger et bygg fremover, beholder den snudde kontrakten: Den styrer hvordan arbeidet bygges og avgj\xf8r aldri hva som skal bygges."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xi-ingeni\xf8rmessig-grundighet-sporingsdisiplinen",children:"XI. Ingeni\xf8rmessig grundighet: sporingsdisiplinen"}),"\n",(0,s.jsxs)(n.p,{children:['Disiplinen "avstem, aldri bare legg til" (',(0,s.jsx)(n.code,{children:"\xa7V"}),") trenger et underlag som overlever refaktoreringer. Et funn m\xe5 forbli ett element gjennom hver fase som ber\xf8rer det, og en omd\xf8pt eller flyttet fil m\xe5 ikke bryte kjeden. SDH l\xf8ser dette med ",(0,s.jsx)(n.strong,{children:"identitet etter navn"})," og ",(0,s.jsx)(n.strong,{children:"stier som bare finnes i sporingen"}),"."]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Definisjon"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Identitet etter navn:"})," Identiteten til et funn er navnet, skrevet likt i hver artefakt. Teksten inneholder navnet, aldri en sti. Filstier ligger bare i sporingskartet, s\xe5 en omd\xf8pt eller flyttet fil bryter koblingen p\xe5 n\xf8yaktig ett sted."]}),"\n"]}),"\n",(0,s.jsxs)(n.p,{children:["Hvert funn fra detect er ett sporet element. Identiteten er ",(0,s.jsx)(n.strong,{children:"navnet"}),", seksjonstittelen, skrevet likt i kartleggingen, forsvarsplanen og herdingsloggen. De senere fasene gjenbruker navnet ordrett n\xe5r de handler p\xe5 det samme elementet, og verify skriver konklusjonen sin i herdingsloggen under det samme navnet. Sporingskartet inneholder sporing og ingenting annet, \xe9n oppf\xf8ring per element:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-json",children:'{ "name": "File uploads", "paths": ["src/routes/upload.ts"] }\n'})}),"\n",(0,s.jsx)(n.p,{children:"Kartet registrerer ingen tekst, ingen merknader, ingen separat identifikator og ingen fase. Tekstartefaktene b\xe6rer formuleringene, og kartet b\xe6rer bare identitet og stier. Filstier er det eneste flyktige, og de ligger bare her. En omd\xf8pt eller flyttet fil kan bryte koblingen p\xe5 n\xf8yaktig ett sted, aldri i to kopier som glir fra hverandre."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    detect["kartleggingen"] --\x3e name\n    plan["forsvarsplanen"] --\x3e name\n    harden["herdingsloggen<br/>verify skriver konklusjonen sin her"] --\x3e name\n    name["name = &quot;File uploads&quot;<br/>teksten b\xe6rer navnet, aldri en sti"]\n    name -.-> tracking\n    tracking["sporingskartet<br/>{ name: &quot;File uploads&quot;,<br/>paths: [&quot;src/routes/upload.ts&quot;] }<br/>stien ligger bare her, s\xe5 en omd\xf8ping retter bare denne oppf\xf8ringen"]\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figur 5."})," Transportb\xe5ndet for identitet. Ett funnavn g\xe5r gjennom hver artefakt, mens stien bare ligger i sporingskartet, s\xe5 en omd\xf8ping rettes p\xe5 ett sted."]}),"\n",(0,s.jsxs)(n.p,{children:["To handlinger vedlikeholder kartet i den vanlige flyten, og en tredje st\xe5r for seg selv som vedlikehold. ",(0,s.jsx)(n.strong,{children:"Track"})," er tilleggsregistrering: En fase rapporterer funnene den skrev, og motoren registrerer de nye og f\xf8lger en omd\xf8pt sti for resten, og klassifiserer hvert funn som nytt, flyttet eller uendret. Den fjerner aldri noe fasen ikke rapporterte. ",(0,s.jsx)(n.strong,{children:"Untrack"})," tar ut funnene verify lukket: I \xe9n deterministisk gjennomgang destillerer den hvert av dem til en historikkoppf\xf8ring, fjerner hele seksjonen fra artefaktene, sletter en artefakt der det siste funnet er borte, og fjerner sporingsoppf\xf8ringen, s\xe5 agenten gj\xf8r ingenting av dette for h\xe5nd. Der den deterministiske gjennomgangen ikke trygt kan g\xe5 videre (et uttatt navn som fortsatt siteres i teksten til et annet funn), flagger den stedet for agenten i stedet for \xe5 gjette en endring. Disse to er det fasene kaller mens de kj\xf8rer. ",(0,s.jsx)(n.strong,{children:"Repair"})," er vedlikeholdshandlingen: En fase delegerer automatisk til den n\xe5r dens egen avstemming finner sporingen inkonsistent (en registrert sti som ikke lenger finnes), og ellers kj\xf8res den ved behov. Den justerer hele kartet p\xe5 \xe9n gang, leser hver artefakt og den n\xe5v\xe6rende koden, retter stiene for hvert element og viser frem det den ikke kan avgj\xf8re alene: et foreldrel\xf8st element (et sporet element ingen artefakt nevner lenger) eller en mulig omd\xf8ping (et element der stiene matcher et annet rapportert navn)."]}),"\n",(0,s.jsx)(n.p,{children:"Repair er vedlikehold, ikke en sjette fase. Den r\xf8rer verken koden til brukeren eller tekstartefaktene, bare sporingen. Den leser kildekoden til brukeren av bare \xe9n grunn, for \xe5 finne den nye stien til en omd\xf8pt fil, og den skriver aldri sikkerhetsinnhold. Mennesket har siste ord i den ene avgj\xf8relsen motoren nekter \xe5 gjette: om et element som har forsvunnet, ble l\xf8st eller bare fikk nytt navn. Det er bedre \xe5 sp\xf8rre enn \xe5 gjette, fordi et element som droppes ved en feil, bryter kjeden."}),"\n",(0,s.jsx)(n.p,{children:"Metodikken bruker sin egen forsvarsdisiplin p\xe5 seg selv. De deterministiske motorene kalles som kommandolinjeprogrammer, og hver verdi sendes som et eget prosessargument, som holder den uskadelig, s\xe5 en verdi med anf\xf8rselstegn eller backticks aldri kan injiseres i kommandoen. En ukjent kontroll feiler i stedet for \xe5 svare, s\xe5 en feilstavet kontroll aldri leses som et rent resultat. SDH unntar ikke sin egen infrastruktur fra prinsippet om sikker som standard."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xii-b\xe6reren-agentuavhengig-arkitektur-som-bevis-p\xe5-portabilitet",children:"XII. B\xe6reren: agentuavhengig arkitektur som bevis p\xe5 portabilitet"}),"\n",(0,s.jsx)(n.p,{children:"For at SDH skal bli en konvensjon andre tar i bruk, kan den ikke v\xe6re bundet til \xe9n agent eller \xe9n stack, s\xe5 b\xe6reren holder tre ansvarsomr\xe5der adskilt (figur 6). Lagune beviser at dette er mulig."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Sikkerhetsverdien"})," skrives \xe9n gang og vet ingenting om hvilken agent som kj\xf8rer den: faseinstruksjonene og malene de fyller ut, kunnskapskatalogen og de deterministiske motorene. ",(0,s.jsx)(n.strong,{children:"Leveransen"})," er tynn: Den eneste oppgaven er \xe5 bringe den verdien til en gitt agent i den formen og p\xe5 det stedet agenten forventer, og den har ingen egen sikkerhetslogikk. ",(0,s.jsx)(n.strong,{children:"Prosjektets tilstand"})," h\xf8rer til prosjektet: sikkerhetsprinsippene, faseartefaktene, sporingskartet, kategoriene det valgte og prosjektets egne spesialiseringer, committet og mulig \xe5 gjennomg\xe5 som enhver annen del av koden."]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    value["sikkerhetsverdien, skrevet \xe9n gang<br/>faseinstruksjoner \xb7 maler \xb7 kunnskapskatalog \xb7 deterministiske motorer<br/>vet ingenting om hvilken agent som kj\xf8rer den"]\n    delivery["leveranse<br/>bringer verdien til hver agent i den formen den forventer<br/>har ingen sikkerhetslogikk"]\n    agent["agenten<br/>kj\xf8rer fasene"]\n    project["prosjektets tilstand<br/>committet sammen med koden<br/>sikkerhetsprinsipper \xb7 faseartefakter \xb7 sporing \xb7 kategorier \xb7 egne spesialiseringer"]\n    value --\x3e delivery --\x3e agent\n    agent --\x3e|"leser og skriver"| project\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figur 6."})," Den agentuavhengige b\xe6reren. Sikkerhetsverdien skrives \xe9n gang, en tynn leveranse bringer den til hver agent, og tilstanden forblir prosjektets."]}),"\n",(0,s.jsx)(n.p,{children:"Fordi leveransen ikke har noen sikkerhetslogikk, endrer m\xe5ten den bygges p\xe5 ingenting i SDH. En b\xe6rer kan bygge leveransen selv eller overlate den til et \xf8kosystem som allerede distribuerer skills for agenter, slik referanseimplementasjonen gj\xf8r, og fasene, artefaktene og garantiene deres forblir de samme. Ingenting av dette er heller spesifikt for et spr\xe5k eller en kj\xf8retid. Referanseimplementasjonen er tilfeldigvis skrevet i \xe9n stack, men metodikken er grensen mellom disse ansvarsomr\xe5dene, ikke verkt\xf8ykjeden som bygger dem. Det samme designet kunne v\xe6rt implementert p\xe5 nytt i et helt annet spr\xe5k uten \xe5 endre hva SDH er."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xiii-gjennomg\xe5tt-eksempel-sdh-fra-start-til-slutt",children:"XIII. Gjennomg\xe5tt eksempel: SDH fra start til slutt"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Gjennomg\xe5tt eksempel"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Defensiv herding av en opplastings- og adminflate."}),"\n",(0,s.jsx)(n.strong,{children:"Kontekst:"})," en liten app som tar imot filopplastinger fra brukere og lister dem p\xe5 en adminside.\n",(0,s.jsx)(n.strong,{children:"M\xf8nster:"})," charter \u2192 detect (med kunnskap ved behov aktivert av konteksten) \u2192 plan \u2192 harden \u2192 verify, med \xe9n lukking og \xe9n reell feil.\n",(0,s.jsx)(n.strong,{children:"Resultat (evne):"})," \xe9n risiko verifisert lukket og tatt ut av hele kjeden, og ett sikringstiltak verifisert som ",(0,s.jsx)(n.em,{children:"ikke"})," lukket og sendt tilbake til harden. Konklusjonen gjenspeiler koden, ikke loggen."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.em,{children:"Dette er et illustrerende eksempel p\xe5 mekanikken i metodikken, ikke en studie m\xe5lt i felt, og det rapporterer ingen m\xe5ltall for effekt."})}),"\n",(0,s.jsxs)(n.p,{children:["\xc9n sammenhengende gjennomgang viser metodikken i drift, ikke bare delene. Vi utvider tr\xe5den om filopplasting fra ",(0,s.jsx)(n.code,{children:"\xa7IV"})," med en aktivering av kunnskap ved behov og en lukking, og vi tar med \xe9n reell feil."]}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"charter"}),' foresl\xe5r prinsippet "Alle inndata er ikke-klarerte til de er validert", med risikoen i et enkelt spr\xe5k: Inndata som ikke sjekkes, er den vanligste m\xe5ten et system blir brutt p\xe5.']}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"detect"})," skanner opplastingsruten og den lille adminsiden som lister opplastede filer. Den oppdager funnet for opplastingen (handleren stoler p\xe5 MIME-typen fra klienten). Adminsiden kj\xf8rer i nettleseren, en kontekst som prompt-on-demand (",(0,s.jsx)(n.code,{children:"\xa7VII"}),") gjenkjenner, s\xe5 detect laster spesialiseringen for den konteksten og viser et funn nummer to: et sted der et filnavn skrives inn i siden som markup i stedet for tekst, s\xe5 et manipulert navn kan kj\xf8re som skript i nettleseren til den bes\xf8kende. Spesialiseringer hvis kontekst mangler i dette omfanget, lastes aldri, og hver gang en hoppes over, registreres det med frav\xe6ret lest ut av koden."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"plan"})," gir utbedringen for opplastingen prioritet kritisk, knyttet til prinsippet: Sjekk den faktiske filtypen og st\xf8rrelsen, gi filen nytt navn ved lagring, lagre der kode ikke kan kj\xf8res. Den gir den andre utbedringen prioritet h\xf8y: Vis filnavnet som tekst, ikke markup."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"harden"})," tar i bruk utbedringen for opplastingen f\xf8rst (h\xf8yeste prioritet) og registrerer den som Applied, og deretter den andre, Applied."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"verify"})," leser hvert sted og holder koden opp mot loggen. Sikringstiltaket for opplastingen holder: Handleren oppdager den faktiske typen ut fra innholdet, h\xe5ndhever en st\xf8rrelsesgrense og avviser resten. Konklusjon: Risk closed. Verify tar funnet for opplastingen ut av hele kjeden, og det destillerte sammendraget havner i historikken."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'Den reelle feilen f\xf8lger. Anta at den andre utbedringen fra harden la til en trygg hjelpefunksjon for tekstvisning, men lot det gamle kallet som skriver markup, fortsatt v\xe6re n\xe5bart via en annen kodesti. Verify leser siden, ser den trygge hjelpefunksjonen og ser ogs\xe5 at den usikre stien fortsatt er aktiv. Sikringstiltaket finnes, men risikoen er ikke lukket. Verify nekter \xe5 myke opp konklusjonen for \xe5 passe loggen. Den returnerer "Risk not closed", registrerer gapet og peker tilbake til harden. Et sikringstiltak som ikke h\xe5ndterer risikoen fullt ut, er ikke godkjent.'}),"\n",(0,s.jsx)(n.p,{children:"Dette er metodikkens karakter i ett eksempel: kontekstbevisst oppdagelse, prioriterte utbedringer knyttet til prinsipper, forsiktig gjennomf\xf8ring og en verifisering som rapporterer den faktiske tilstanden i koden, uansett hva loggen sier."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xiv-n\xe5r-du-b\xf8r-bruke-sdh-og-grensene",children:"XIV. N\xe5r du b\xf8r bruke SDH, og grensene"}),"\n",(0,s.jsxs)(n.p,{children:["SDH er sjelden uforholdsmessig slik en tung prosess kan v\xe6re, fordi den er tilstandsuavhengig og lukkbar: Den kan skaleres ned til \xe9n enkelt fil og \xe9n enkelt problemstilling, og den kommer til ro i stedet for \xe5 etterlate en varig byrde. Grensen er ikke prosjektets st\xf8rrelse, men ",(0,s.jsx)(n.strong,{children:"dybden i sikkerhetsgarantien"}),"."]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    q1{"Gj\xf8r koden noe som er relevant for sikkerheten?<br/>(inndata, autentisering, data, hemmeligheter, eksterne kall)"}\n    q1 --\x3e|nei| little["SDH tilf\xf8rer lite her."]\n    q1 --\x3e|ja| q2{"Kj\xf8r SDH. Finnes det et compliance-krav<br/>eller en egen sikkerhetsfunksjon?"}\n    q2 --\x3e|nei| baseline["SDH er et forsvarbart grunnlag."]\n    q2 --\x3e|ja| carrier["SDH er den strukturerte b\xe6reren:<br/>den st\xf8tter ekspertgjennomgang og revisjon,<br/>den erstatter dem ikke."]\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Figur 7."})," N\xe5r du b\xf8r bruke SDH. Forgreningen sp\xf8r f\xf8rst om sikkerhetsrelevans, deretter om dybden i sikkerhetsgarantien, aldri om prosjektets st\xf8rrelse."]}),"\n",(0,s.jsx)(n.p,{children:"Der SDH n\xe5r grensen sin: atferd som bare viser seg n\xe5r systemet kj\xf8rer (verify leser kode, den kj\xf8rer ikke systemet), risiko som avhenger av konfigurasjon eller et milj\xf8 agenten ikke kan lese, og kontekster med mye p\xe5 spill der ekspertgjennomgang uansett er p\xe5krevd. I hvert av disse tilfellene tilf\xf8rer SDH fortsatt verdi som en strukturert f\xf8rste gjennomgang, men den er et gulv, ikke et tak."}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:(0,s.jsx)(n.strong,{children:"Kjerneinnsikt"})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Grensen:"})," Begrensningen til SDH er dybden i sikkerhetsgarantien, ikke prosjektets st\xf8rrelse. Den kan fungere som et forsvarbart grunnlag nesten overalt, og den st\xf8tter ekspertgjennomgang der mye st\xe5r p\xe5 spill, men den erstatter ikke testing av et kj\xf8rende system eller vurderingen til en sikkerhetsekspert."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xv-diskusjon-posisjonering-grenser-og-hva-sdh-ikke-hevder",children:"XV. Diskusjon: posisjonering, grenser og hva SDH ikke hevder"}),"\n",(0,s.jsx)(n.p,{children:"SDH er presis om grensene sine."}),"\n",(0,s.jsx)(n.h3,{id:"den-utvider-den-erstatter-ikke",children:"Den utvider, den erstatter ikke"}),"\n",(0,s.jsxs)(n.p,{children:["SDH erstatter ikke sikkerhetsfolk eller spesialiserte Blue Team-verkt\xf8y. Den utvider utviklerens kunnskap (",(0,s.jsx)(n.code,{children:"\xa7VI"}),"). En n\xf8ktern p\xe5stand er den riktige: Brukt godt ",(0,s.jsx)(n.strong,{children:"kan"})," SDH lukke reelle risikoer effektivt, s\xe6rlig for prosjekter som ellers ikke ville f\xe5tt noen sikkerhetsgjennomgang i det hele tatt. Den er ingen garanti, og den er ingen erstatning for ekspertgjennomgang der mye st\xe5r p\xe5 spill."]}),"\n",(0,s.jsx)(n.h3,{id:"kun-defensiv-per-konstruksjon",children:"Kun defensiv, per konstruksjon"}),"\n",(0,s.jsx)(n.p,{children:"SDH reviderer, herder og verifiserer. Den lager aldri offensive verkt\xf8y, exploits eller teknikker for \xe5 unng\xe5 deteksjon for \xe5 gj\xf8re skade. Sikkerhetsinnhold med dobbel bruk er bare akseptabelt i en tydelig defensiv og autorisert ramme. Dette er en absolutt grense, ikke en preferanse."}),"\n",(0,s.jsx)(n.h3,{id:"verifiseringen-er-reell-ikke-teater",children:"Verifiseringen er reell, ikke teater"}),"\n",(0,s.jsx)(n.p,{children:'Verify verifiserer ved \xe5 lese koden og holde den opp mot loggen, ikke ved \xe5 kj\xf8re systemet. Dette er statisk verifisering: Den bekrefter at et sikringstiltak finnes og er korrekt i koden, og den beviser ikke at sikringstiltaket holder under angrep ved kj\xf8ring. Derfor er "Cannot tell from the code" en legitim konklusjon, ikke en feil skjult bak et best\xe5tt resultat. N\xe5r belegget ikke finnes i koden (det avhenger av konfigurasjon, eller av en sti agenten ikke kan lese), sier SDH det i stedet for \xe5 gjette.'}),"\n",(0,s.jsx)(n.h3,{id:"determinismen-er-avgrenset-og-navngitt",children:"Determinismen er avgrenset og navngitt"}),"\n",(0,s.jsxs)(n.p,{children:["Det meste av SDH bygger p\xe5 agentens resonnering, og det er det som gj\xf8r kontekstbevisstheten mulig. Determinisme er forbeholdt de deterministiske motorene: kontrollene en spesialisering kan ha (",(0,s.jsx)(n.code,{children:"\xa7VII"}),"), og sporingsmotoren (",(0,s.jsx)(n.code,{children:"\xa7XI"}),"). Dokumentet visker ikke ut dette skillet. Der et resultat er deterministisk, er det resultatet fra et program. Der det er resonnert, er det agentens lesning av koden, med brukeren som den som har siste ord."]}),"\n",(0,s.jsx)(n.h3,{id:"kostnad-og-skala",children:"Kostnad og skala"}),"\n",(0,s.jsxs)(n.p,{children:["En full gjennomgang bruker mange tokens. De manuelle modusene (",(0,s.jsx)(n.code,{children:"\xa7VI"}),", ",(0,s.jsx)(n.code,{children:"\xa7VIII"}),") finnes delvis for \xe5 holde kostnaden i forhold til problemstillingen."]}),"\n",(0,s.jsx)(n.h3,{id:"brukeren-har-siste-ord",children:"Brukeren har siste ord"}),"\n",(0,s.jsx)(n.p,{children:"SDH ber mennesket avgj\xf8re om et element fikk nytt navn eller ble l\xf8st, og godkjenningen av kodeendringene ligger der brukeren allerede styrer agenten sin, i tillatelsesmodusen agenten kj\xf8rer i. Metodikken foresl\xe5r og verifiserer. Den overstyrer ikke personen."}),"\n",(0,s.jsx)(n.h3,{id:"innvendinger-og-svar",children:"Innvendinger og svar"}),"\n",(0,s.jsx)(n.p,{children:"En rettferdig skeptiker vil komme med flere innvendinger. De vesentlige er verdt \xe5 stille med skeptikerens egne ord."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"Er ikke dette bare en statisk analysator med en LLM skrudd p\xe5?"'})," Nei. En statisk analysator kj\xf8rer alle reglene den har som standard. SDH oppdager f\xf8rst hva systemet er, og henter deretter den relevante kunnskapen (",(0,s.jsx)(n.code,{children:"\xa7II"}),", ",(0,s.jsx)(n.code,{children:"\xa7VII"}),"), og den ",(0,s.jsx)(n.em,{children:"bygger inn"})," en deterministisk kontroll bare der en risikoklasse har en skarp beslutningsprosedyre. Resonneringen starter med konteksten, og determinismen er m\xe5lrettet."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"Er ikke dette bare en sikkerhetssjekkliste?"'})," Nei. SDH snur sjekklisten: Oppdagelsen kommer f\xf8rst, og kunnskapen hentes inn for det prosjektet faktisk gj\xf8r (",(0,s.jsx)(n.code,{children:"\xa7II"}),", ",(0,s.jsx)(n.code,{children:"\xa7VII"}),")."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"Er ikke dette bare SDD med ny merkevare for sikkerhet?"'})," Nei. SDH l\xe5ner strukturen fra SDD og snur kontrakten: Autoritet, forutsatt tilstand, sluttbetingelse og hvem den tjener, er alle forskjellige (",(0,s.jsx)(n.code,{children:"\xa7X"}),"). Samme maskineri, motsatt retning."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:'"Hallusinerer ikke en metode basert p\xe5 KI-resonnering bare funn?"'}),' Designet begrenser muligheten til \xe5 finne p\xe5 i stedet for \xe5 stole p\xe5 at modellen oppf\xf8rer seg. Detect registrerer bare det koden underbygger ("oppdage, ikke finne p\xe5", ',(0,s.jsx)(n.code,{children:"\xa7IV"}),'), verify holder koden opp mot loggen og kan svare "Cannot tell from the code" (',(0,s.jsx)(n.code,{children:"\xa7XV"}),"), deterministiske kontroller forankrer de avgj\xf8rbare tilfellene (",(0,s.jsx)(n.code,{children:"\xa7VII"}),"), og brukeren har siste ord. Det gj\xf8r ikke agenten ufeilbarlig, men det gj\xf8r p\xe5standene den kommer med, mulige \xe5 kontrollere."]}),"\n",(0,s.jsx)(n.p,{children:'En merknad om posisjonering. SDH defineres her uavhengig av referanseimplementasjonen. De fem fasene, sikkerhetsprinsippene rammet inn rundt risiko, "avstem, aldri bare legg til" og lukkbarheten som f\xf8lger av det, kunnskap via prompt-on-demand, den forebyggende modusen, sporing med identitet etter navn og grensen om kun forsvar er metodikken. Et annet team kunne implementert dem i en annen stack og et annet agent\xf8kosystem, og resultatet ville fortsatt v\xe6rt SDH. Lagune er beviset, ikke definisjonen.'}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xvi-fallgruver-og-hvordan-sdh-unng\xe5r-dem-strukturelt",children:"XVI. Fallgruver, og hvordan SDH unng\xe5r dem strukturelt"}),"\n",(0,s.jsx)(n.p,{children:"Metodikker i denne familien har et kjent sett med feilmoduser. Svaret SDH har p\xe5 de fleste av dem, er strukturelt, bygget inn i flyten i stedet for overlatt til disiplin."}),"\n",(0,s.jsxs)(n.table,{children:[(0,s.jsx)(n.thead,{children:(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.th,{children:"Fallgruve"}),(0,s.jsx)(n.th,{children:"Feilen"}),(0,s.jsx)(n.th,{children:"Det strukturelle svaret i SDH"})]})}),(0,s.jsxs)(n.tbody,{children:[(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Forfalne spesifikasjoner, utdatert etterslep"}),(0,s.jsx)(n.td,{children:"Artefakter samler d\xf8de oppf\xf8ringer ingen stoler p\xe5"}),(0,s.jsxs)(n.td,{children:['"Avstem, aldri bare legg til" (',(0,s.jsx)(n.code,{children:"\xa7V"}),"): Hver kj\xf8ring sjekker hver oppf\xf8ring p\xe5 nytt og fjerner det som er l\xf8st"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Falsk trygghet, best\xe5tt resultat"}),(0,s.jsx)(n.td,{children:"Et sikringstiltak som finnes, antas \xe5 lukke risikoen"}),(0,s.jsxs)(n.td,{children:['Verify holder koden opp mot loggen, s\xe5 "Risk not closed" og "Cannot tell" er fullverdige konklusjoner (',(0,s.jsx)(n.code,{children:"\xa7IV"}),", ",(0,s.jsx)(n.code,{children:"\xa7XV"}),")"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Sjekklisteflom"}),(0,s.jsx)(n.td,{children:"Generiske punkter skjuler den ene risikoen som betyr noe"}),(0,s.jsxs)(n.td,{children:["Kontekstbevisst fremfor generisk, med prompt-on-demand som bare laster det omfanget krever (",(0,s.jsx)(n.code,{children:"\xa7VII"}),")"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Innl\xe5sing i verkt\xf8y"}),(0,s.jsx)(n.td,{children:"Metoden er sveiset fast til \xe9n leverand\xf8r eller agent"}),(0,s.jsxs)(n.td,{children:["Agentuavhengig b\xe6rer: Sikkerhetsverdien skrives \xe9n gang, og leveransen til hver agent har ingen sikkerhetslogikk (",(0,s.jsx)(n.code,{children:"\xa7XII"}),")"]})]}),(0,s.jsxs)(n.tr,{children:[(0,s.jsx)(n.td,{children:"Den endel\xf8se l\xf8kken"}),(0,s.jsx)(n.td,{children:"Etterslepet lukkes aldri, arbeidet kommer aldri til ro"}),(0,s.jsxs)(n.td,{children:["Lukkbarhet og tilstanden i ro (",(0,s.jsx)(n.code,{children:"\xa7V"}),")"]})]})]})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Tabell 4."})," Kjente fallgruver i denne metodikkfamilien og det strukturelle svaret SDH har p\xe5 hver av dem."]}),"\n",(0,s.jsx)(n.p,{children:"Poenget er \xe5 navngi fallgruven og peke p\xe5 mekanismen: Dette er ikke advarsler om \xe5 v\xe6re forsiktig, men egenskaper ved flyten."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xvii-videre-arbeid",children:"XVII. Videre arbeid"}),"\n",(0,s.jsx)(n.p,{children:"Metodikken og referanseimplementasjonen har tydelige neste steg."}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Utvide kunnskapskatalogen:"}),"\nHvert tillegg beholder formen fra ",(0,s.jsx)(n.code,{children:"\xa7VII"}),": en kunnskapsfil og en katalograd, ingen ny kommando. Veien p\xe5 brukersiden finnes allerede der: Brukeren destillerer sine egne spesialiseringer ved behov. Flere innebygde spr\xe5k, kj\xf8retider og risikoklasser, hver i en kategori, er retningen p\xe5 vedlikeholdersiden, og spesialiseringene forventes \xe5 utvikle seg."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Flere deterministiske kontroller:"}),"\nDer en risikoklasse har en skarp beslutningsprosedyre, kan en spesialisering ha en deterministisk kontroll som forankrer agentens resonnering i en repeterbar konklusjon. \xc5 utvide dette til flere risikoklasser er en naturlig retning."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Empirisk evaluering:"}),"\nDet viktigste \xe5pne sp\xf8rsm\xe5let er m\xe5lt effekt: kvaliteten p\xe5 lukkingen og andelen feilaktige konklusjoner p\xe5 tvers av virkelige kodebaser. En studie av sikkerhetsresultatene til SDH er fremtidig arbeid, og p\xe5standene her er avgrenset deretter."]}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"xviii-konklusjon",children:"XVIII. Konklusjon"}),"\n",(0,s.jsx)(n.p,{children:"KI-assistert utvikling \xe5pnet et sikkerhetsgap som generiske sjekklister ikke kan fylle, fordi risikoen som betyr noe, er spesifikk for det et system faktisk gj\xf8r, og personen som leverer det, kanskje ikke vet hva det skal sp\xf8rres om. SDH lukker dette gapet med en kontekstbevisst, kun defensiv og lukkbar flyt der sikkerhetskunnskapen ligger i metodikken og spesialiseringene som lastes ved behov, et grunnlag enhver bruker kan bygge videre p\xe5. Den oppdager den reelle konteksten til systemet, prioriterer risikoene den konteksten f\xf8rer med seg, tar i bruk utbedringer med omhu og verifiserer hver av dem, og tar deretter ut det den har lukket, s\xe5 hvert funn n\xe5r en sluttilstand. Det samme forsvaret kj\xf8rer ogs\xe5 forebyggende mens nytt arbeid bygges, s\xe5 det flyten lukker, forblir lukket. Den tilpasser seg enhver utviklingstilstand i enhver stack, og den utvider utviklerens kunnskap i stedet for \xe5 erstatte menneskene og verkt\xf8yene som allerede gj\xf8r den jobben."}),"\n",(0,s.jsx)(n.p,{children:"Lagune er beviset, men bidraget er konvensjonen. SDH tilbys som den essensielle sikkerhetsflyten for tiden med KI-assistert utvikling, slik at andre kan ta den i bruk, forbedre den og implementere den i sine egne stacker."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"referanser",children:"Referanser"}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[1]"}),' D. B. Piskala, "Spec-Driven Development: From Code to Contract in the Age of AI Coding Assistants," arXiv preprint arXiv:2602.00180v1 [cs.SE], Jan. 2026. (Submitted to AIWare 2026.) [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://arxiv.org/abs/2602.00180",children:"https://arxiv.org/abs/2602.00180"})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[2]"}),' GitHub, "Spec Kit: Toolkit for Spec-Driven Development." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/github/spec-kit",children:"https://github.com/github/spec-kit"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[3]"}),' Fission AI, "OpenSpec: Spec-Driven Development for AI Coding Assistants." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/Fission-AI/OpenSpec",children:"https://github.com/Fission-AI/OpenSpec"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[4]"}),' B. Chess and G. McGraw, "Static Analysis for Security," IEEE Security & Privacy, vol. 2, no. 6, pp. 76-79, 2004, doi: 10.1109/MSP.2004.111.']}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[5]"}),' OWASP Foundation, "Source Code Analysis Tools." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://owasp.org/www-community/Source_Code_Analysis_Tools",children:"https://owasp.org/www-community/Source_Code_Analysis_Tools"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[6]"}),' OWASP Foundation, "OWASP Top 10:2021." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://owasp.org/Top10/",children:"https://owasp.org/Top10/"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[7]"}),' MITRE, "Common Weakness Enumeration (CWE)." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://cwe.mitre.org/",children:"https://cwe.mitre.org/"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[8]"}),' N. Perry, M. Srivastava, D. Kumar, and D. Boneh, "Do Users Write More Insecure Code with AI Assistants?," in Proc. ACM SIGSAC Conf. on Computer and Communications Security (CCS \'23), 2023, pp. 2785-2799, doi: 10.1145/3576915.3623157. [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://arxiv.org/abs/2211.03622",children:"https://arxiv.org/abs/2211.03622"})]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[9]"}),' J. Davis and contributors, "safe-regex: Detect Possibly Catastrophic, Exponential-Time Regular Expressions." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/davisjam/safe-regex",children:"https://github.com/davisjam/safe-regex"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[10]"}),' D. Soshnikov, "regexp-tree: Regular Expressions Processor in JavaScript." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/DmitrySoshnikov/regexp-tree",children:"https://github.com/DmitrySoshnikov/regexp-tree"}),". Accessed: 2026."]}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"[11]"}),' T. Jenkinson, "redos-detector: A CLI and Library to Score How Vulnerable a Regex Pattern Is to ReDoS Attacks." [Online]. Available: ',(0,s.jsx)(n.a,{href:"https://github.com/tjenkinson/redos-detector",children:"https://github.com/tjenkinson/redos-detector"}),". Accessed: 2026."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"vedlegg-a-prinsippene-ordrett",children:"Vedlegg A: prinsippene, ordrett"}),"\n",(0,s.jsxs)(n.ol,{children:["\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Sikker som standard, i et enkelt spr\xe5k, likt for alle:"}),"\nHver standardinnstilling, melding og utbedring m\xe5 v\xe6re sikker fra start og forst\xe5elig for enhver bruker, utvikler eller ikke. Ingen brukergruppe er privilegert fremfor en annen."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Kontekstbevisst fremfor generisk:"}),"\nHver fase m\xe5 starte fra konteksten som ble oppdaget i detect, og handle ut fra det systemet faktisk gj\xf8r. Foretrekk anbefalinger som er spesifikke for den konteksten, fremfor generiske sjekklister. Sikkerhetskunnskapen ligger i spesifikasjonen og spesialiseringene som lastes ved behov, og utvider det brukeren tar med seg."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Fleksibel fremfor rigid:"}),"\nSDH tilpasser seg prosjektet og brukeren. Prinsipper, krav og anbefalinger er utgangspunkter, ikke en fast kontrakt. La brukeren omformulere, droppe, legge til eller snevre inn hva som helst. Fleksibilitet svekker aldri grunnlaget som er sikkert som standard, den lar bare brukeren forme hvordan det brukes."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Avstem, aldri bare legg til:"}),"\nArtefakter er levende dokumenter, ikke logger. Avstem hver eksisterende oppf\xf8ring mot den n\xe5v\xe6rende sannheten n\xe5r en fase kj\xf8res p\xe5 nytt: Behold det som fortsatt holder, skriv om det som er endret, og fjern det som ikke lenger gjelder. Lukking er den samme avstemmingen, f\xf8rt helt til ende."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Kun defensiv:"}),"\nSDH reviderer, herder og verifiserer. Den lager aldri offensive verkt\xf8y, exploits for ondsinnet bruk eller teknikker for \xe5 unng\xe5 deteksjon for \xe5 gj\xf8re skade. Sikkerhetsinnhold med dobbel bruk er bare akseptabelt i en tydelig defensiv og autorisert ramme."]}),"\n",(0,s.jsxs)(n.li,{children:[(0,s.jsx)(n.strong,{children:"Spec-first, agentdrevet, innrettet mot sikkerhet:"}),"\nBygg arbeidsflyten p\xe5 en velpr\xf8vd struktur: maler, kommandoer, styrende sikkerhetsprinsipper og en agent som kj\xf8rer fasene. Implementer den strukturen p\xe5 nytt med et defensivt form\xe5l."]}),"\n"]})]})}function k(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(a,{...e})}):a(e)}}}]);